import collections

# Define blocks
blocks = ["block1", "block2"]

# State representation:
# hand: None or block name held
# pos: dict mapping block -> support ('table' or another block)
def initial_state():
    # Start by holding block2, block1 on table
    hand = "block2"
    pos = {"block1": "table"}  # block2 is not on anything because it's held
    return (hand, frozenset(pos.items()))

def is_clear(state, b):
    hand, pos_items = state
    pos = dict(pos_items)
    # a block is clear if no other block is on it
    return all(sup != b for sup in pos.values())

def goal_test(state):
    hand, pos_items = state
    pos = dict(pos_items)
    # both blocks on table
    return pos.get("block1") == "table" and pos.get("block2") == "table"

def successors(state):
    hand, pos_items = state
    pos = dict(pos_items)
    succ = []
    # Helper to create new state
    def make_state(new_hand, new_pos):
        return (new_hand, frozenset(new_pos.items()))
    # pickup B
    if hand is None:
        for b in blocks:
            if pos.get(b) == "table" and is_clear(state, b):
                new_pos = pos.copy()
                del new_pos[b]
                succ.append( (make_state(b, new_pos), f"(pickup {b})") )
    # putdown B
    if hand is not None:
        b = hand
        new_pos = pos.copy()
        new_pos[b] = "table"
        succ.append( (make_state(None, new_pos), f"(putdown {b})") )
    # unstack B1 B2
    if hand is None:
        for b1 in blocks:
            sup = pos.get(b1)
            if sup and sup != "table" and is_clear(state, b1):
                # b1 is on sup and clear
                new_pos = pos.copy()
                del new_pos[b1]
                succ.append( (make_state(b1, new_pos), f"(unstack {b1} {sup})") )
    # stack B1 B2
    if hand is not None:
        b1 = hand
        for b2 in blocks:
            if b2 != b1 and is_clear(state, b2):
                new_pos = pos.copy()
                new_pos[b1] = b2
                succ.append( (make_state(None, new_pos), f"(stack {b1} {b2})") )
    return succ

def bfs():
    start = initial_state()
    frontier = collections.deque()
    frontier.append( (start, []) )
    visited = set()
    visited.add(start)
    while frontier:
        state, path = frontier.popleft()
        if goal_test(state):
            return path
        for nxt_state, action in successors(state):
            if nxt_state not in visited:
                visited.add(nxt_state)
                frontier.append( (nxt_state, path + [action]) )
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(act)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys
from collections import deque

# ----- Helper functions -----
def clear_blocks(on):
    """Return set of blocks that have nothing on top."""
    occupied = {v for v in on.values() if v != 'table'}
    return {b for b in on if b not in occupied}

def state_key(holding, on):
    """Immutable key for visited set."""
    items = tuple(sorted(on.items()))
    return (holding, items)

def is_goal(on):
    goal = {
        'block4': 'table',
        'block1': 'block4',
        'block10': 'table',
        'block12': 'block10',
        'block14': 'table',
        'block3': 'table',
        'block7': 'block3',
        'block11': 'block7',
        'block8': 'table',
        'block5': 'block8',
        'block6': 'table',
        'block2': 'table',
        'block13': 'table',
        'block9': 'table',
    }
    return on == goal

def generate_actions(holding, on):
    actions = []
    clear = clear_blocks(on)

    # When arm empty: can pickup or unstack
    if holding is None:
        for b in clear:
            if on[b] == 'table':
                actions.append(('pickup', b, None))
            else:
                actions.append(('unstack', b, on[b]))
    else:
        # putdown
        actions.append(('putdown', holding, None))
        # stack onto any clear block except block1 (fragile)
        for y in clear:
            if y == 'block1':
                continue
            actions.append(('stack', holding, y))
    return actions

def apply_action(state, action):
    holding, on = state
    act, x, y = action
    on = on.copy()
    if act == 'pickup':
        # pre: holding None, x clear, on table
        holding = x
        on[x] = None  # temporarily not on anything
    elif act == 'unstack':
        # pre: holding None, x clear, on y
        holding = x
        on[x] = None
    elif act == 'putdown':
        # pre: holding x
        holding = None
        on[x] = 'table'
    elif act == 'stack':
        # pre: holding x, y clear, y != block1
        holding = None
        on[x] = y
    else:
        raise ValueError('unknown action')
    # Clean up None entries (blocks being held are not on anything)
    if holding is not None:
        on[holding] = None
    else:
        # ensure no block has None support
        for k, v in list(on.items()):
            if v is None:
                del on[k]
    return holding, on

def format_action(action):
    act, x, y = action
    if act in ('pickup', 'putdown'):
        return f'({act} {x})'
    else:
        return f'({act} {x} {y})'

# ----- Initial state -----
initial_on = {
    'block12': 'table',
    'block13': 'block12',
    'block1': 'table',
    'block5': 'block1',
    'block10': 'table',
    'block3': 'block10',
    'block11': 'table',
    'block8': 'block11',
    'block14': 'block8',
    'block4': 'block14',
    'block9': 'block4',
    'block6': 'block9',
    'block2': 'block6',
    'block7': 'block2',
}
initial_state = (None, initial_on)

# ----- BFS search -----
queue = deque()
queue.append(initial_state)
visited = {state_key(*initial_state): None}
action_taken = {state_key(*initial_state): None}

found_state = None

while queue:
    state = queue.popleft()
    holding, on = state
    if is_goal(on):
        found_state = state
        break
    for act in generate_actions(holding, on):
        new_state = apply_action(state, act)
        key = state_key(*new_state)
        if key in visited:
            continue
        visited[key] = state
        action_taken[key] = act
        queue.append(new_state)

# ----- Reconstruct plan -----
if found_state is None:
    print("No plan")
    sys.exit(0)

plan = []
key = state_key(*found_state)
while action_taken[key] is not None:
    act = action_taken[key]
    plan.append(format_action(act))
    key = state_key(*visited[key])

for line in reversed(plan):
    print(line)

#!/usr/bin/env python3
import heapq

# Block IDs 1..15
N = 15

# Initial on-relations (0 = table)
init_on = [0] * (N + 1)
init_on[4] = 0
init_on[14] = 4
init_on[8] = 14
init_on[10] = 0
init_on[1] = 0
init_on[12] = 0
init_on[6] = 0
init_on[7] = 6
init_on[5] = 7
init_on[3] = 0
init_on[13] = 3
init_on[15] = 13
init_on[9] = 15
init_on[11] = 0
init_on[2] = 11

# Goal on-relations
goal_on = [0] * (N + 1)
goal_on[13] = 0
goal_on[2] = 13
goal_on[9] = 0
goal_on[1] = 0
goal_on[11] = 0
goal_on[7] = 0
goal_on[12] = 7
goal_on[14] = 0
goal_on[5] = 14
goal_on[8] = 5
goal_on[10] = 0
goal_on[15] = 0
goal_on[4] = 0
goal_on[6] = 4
goal_on[3] = 6

def clear_blocks(on):
    """Return a set of blocks that have nothing on top of them."""
    occupied = set(on[1:]) - {0}
    return {i for i in range(1, N + 1) if i not in occupied}

def heuristic(holding, on):
    """Simple heuristic: number of blocks not in goal position + holding penalty."""
    mismatches = sum(1 for i in range(1, N + 1) if on[i] != goal_on[i])
    return mismatches + (1 if holding is not None else 0)

def state_key(holding, on):
    return (holding, tuple(on[1:]))

def actions(state):
    """Generate feasible actions from a state, respecting the extra constraint."""
    holding, on = state
    clear = clear_blocks(on)
    acts = []
    # Do not move block1 or block4 (additional ordering constraint avoided)
    forbidden_move = {1, 4}
    if holding is None:
        # pickup from table
        for b in clear:
            if on[b] == 0 and b not in forbidden_move:
                acts.append(('pickup', b))
        # unstack
        for b in clear:
            if on[b] != 0 and b not in forbidden_move:
                acts.append(('unstack', b, on[b]))
    else:
        # putdown
        acts.append(('putdown', holding))
        # stack onto any clear block (including block1/4 as destinations)
        for b in clear:
            if b != holding:
                acts.append(('stack', holding, b))
    return acts

def apply(state, act):
    holding, on = state
    on = on[:]  # copy list
    if act[0] == 'pickup':
        _, b = act
        on[b] = None  # temporarily unset; will be held
        return (b, on)
    if act[0] == 'unstack':
        _, b, y = act
        on[b] = None
        return (b, on)
    if act[0] == 'putdown':
        _, b = act
        on[b] = 0
        return (None, on)
    if act[0] == 'stack':
        _, b, y = act
        on[b] = y
        return (None, on)
    raise ValueError('unknown action')

def is_goal(state):
    holding, on = state
    if holding is not None:
        return False
    for i in range(1, N + 1):
        if on[i] != goal_on[i]:
            return False
    return True

def format_action(act):
    name = act[0]
    if name in ('pickup', 'putdown'):
        return f'({name} block{act[1]})'
    elif name == 'unstack':
        return f'({name} block{act[1]} block{act[2]})'
    elif name == 'stack':
        return f'({name} block{act[1]} block{act[2]})'
    else:
        return ''

def a_star():
    start = (None, init_on[:])
    start_key = state_key(*start)
    frontier = [(heuristic(*start), 0, start, [])]  # (f, g, state, path)
    visited = {start_key: 0}
    while frontier:
        f, g, state, path = heapq.heappop(frontier)
        if is_goal(state):
            return path
        for act in actions(state):
            nxt = apply(state, act)
            nxt_key = state_key(*nxt)
            if nxt_key in visited and visited[nxt_key] <= g + 1:
                continue
            visited[nxt_key] = g + 1
            heapq.heappush(frontier, (g + 1 + heuristic(*nxt), g + 1, nxt, path + [act]))
    return None

def main():
    plan = a_star()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(format_action(act))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from collections import deque

# Helper functions
def on_table(state, b):
    return state['on'][b] == 'table'

def clear(state, b):
    return state['clear'][b]

def holding(state):
    return state['hand']

def move(state, action):
    """Return a new state after applying action, or None if illegal."""
    new = {
        'on': state['on'].copy(),
        'clear': state['clear'].copy(),
        'hand': state['hand']
    }
    act = action[0]
    if act == 'pickup':
        b = action[1]
        if holding(state) is not None: return None
        if not on_table(state, b) or not clear(state, b): return None
        new['hand'] = b
        new['clear'][b] = True
    elif act == 'putdown':
        b = action[1]
        if holding(state) != b: return None
        new['hand'] = None
        new['on'][b] = 'table'
        new['clear'][b] = True
    elif act == 'unstack':
        b, y = action[1], action[2]
        if holding(state) is not None: return None
        if state['on'][b] != y: return None
        if not clear(state, b): return None
        new['hand'] = b
        new['on'][b] = None
        new['clear'][b] = True
        new['clear'][y] = True
    elif act == 'stack':
        b, y = action[1], action[2]
        if holding(state) != b: return None
        if not clear(state, y): return None
        new['hand'] = None
        new['on'][b] = y
        new['clear'][b] = True
        new['clear'][y] = False
    else:
        return None
    return new

def count_stacks(state):
    """Number of piles on the table (including single blocks)."""
    bases = {b for b, under in state['on'].items() if under == 'table'}
    return len(bases)

def state_key(state):
    """Hashable representation."""
    items = tuple(sorted((b, state['on'][b]) for b in state['on']))
    hand = state['hand']
    return (items, hand)

# Initial configuration
initial_on = {
    1: 5, 2: 1, 5: 'table', 7: 'table',
    12: 13, 13: 'table',
    11: 14, 14: 'table',
    3: 'table',
    10: 4, 8: 10, 6: 8, 4: 'table',
    9: 'table'
}
# Ensure all 14 blocks present
for i in range(1,15):
    initial_on.setdefault(i, None)

initial_clear = {i: True for i in range(1,15)}
# blocks that have something on top are not clear
for b, under in initial_on.items():
    if isinstance(under, int):
        initial_clear[under] = False

initial_state = {
    'on': initial_on,
    'clear': initial_clear,
    'hand': None
}

# Goal configuration
goal_on = {
    10: 3,
    8: 6,
    4: 'table',
    7: 'table',
    5: 'table',
    13: 7,
    2: 5,
    12: 2,
    14: 12,
    9: 14,
    1: 9,
    11: 1,
    3: 'table',
    6: 'table'
}
for i in range(1,15):
    goal_on.setdefault(i, None)

goal_clear = {i: True for i in range(1,15)}
for b, under in goal_on.items():
    if isinstance(under, int):
        goal_clear[under] = False

goal_state = {
    'on': goal_on,
    'clear': goal_clear,
    'hand': None
}

# Quick impossibility test: goal must respect the 3‑stack limit
goal_stacks = len({b for b, under in goal_on.items() if under == 'table'})
if goal_stacks > 3:
    print("No plan")
    raise SystemExit

# BFS search respecting the 3‑stack limit at every step
actions = []
def gen_actions(state):
    hand = holding(state)
    if hand is None:
        # can pickup from table
        for b in range(1,15):
            if on_table(state, b) and clear(state, b):
                yield ('pickup', b)
        # can unstack
        for b in range(1,15):
            under = state['on'][b]
            if isinstance(under, int) and clear(state, b):
                yield ('unstack', b, under)
    else:
        # can putdown
        yield ('putdown', hand)
        # can stack on any clear block
        for y in range(1,15):
            if y != hand and clear(state, y):
                yield ('stack', hand, y)

def is_goal(state):
    return state['on'] == goal_state['on'] and state['hand'] is None

queue = deque()
queue.append( (initial_state, []) )
visited = set()
found_plan = None

while queue:
    cur_state, plan = queue.popleft()
    key = state_key(cur_state)
    if key in visited:
        continue
    visited.add(key)
    if is_goal(cur_state):
        found_plan = plan
        break
    for act in gen_actions(cur_state):
        nxt = move(cur_state, act)
        if nxt is None:
            continue
        if count_stacks(nxt) > 3:
            continue
        queue.append( (nxt, plan + [act]) )

if found_plan is None:
    print("No plan")
else:
    for act in found_plan:
        if act[0] in ('pickup','putdown'):
            print(f"({act[0]} block{act[1]})")
        else:
            print(f"({act[0]} block{act[1]} block{act[2]})")

#!/usr/bin/env python3
from collections import deque

# ---------- Problem definition ----------
blocks = list(range(1, 11))  # 1..10

# initial locations: 0 = table, otherwise block it sits on
# given: 3,8,10,4,6,5,7 on table; 1 on 10; 2 on 1; 9 on 6
init_loc = {
    1: 10,
    2: 1,
    3: 0,
    4: 0,
    5: 0,
    6: 0,
    7: 0,
    8: 0,
    9: 6,
    10: 0,
}
init_state = (
    None,                                 # holding block (None = empty hand)
    tuple(init_loc[i] for i in blocks),   # locations tuple indexed by block-1
    frozenset()                           # locked blocks (cannot be picked after putdown)
)

# goal conditions
goal_table = {3, 6, 7, 2, 10, 5, 4, 8, 9}
def is_goal(state):
    holding, locs, _ = state
    if holding is not None:
        return False
    # block1 on block8
    if locs[0] != 8:
        return False
    # block8 on table
    if locs[7] != 0:
        return False
    # all other blocks must be on table
    for b in blocks:
        if b == 1:
            continue
        if b == 8:
            continue
        if locs[b-1] != 0:
            return False
    # required set on table (including 9)
    table_blocks = {b for b in blocks if locs[b-1] == 0}
    if not goal_table.issubset(table_blocks):
        return False
    return True

# ---------- Helper functions ----------
def clear_blocks(locs):
    """Return set of blocks that are clear (no block on top)."""
    occupied = set(locs) - {0}
    return {b for b in blocks if b not in occupied}

def apply_action(state, action):
    """Return new state after applying action tuple."""
    holding, locs, locked = state
    locs = list(locs)
    act = action[0]
    if act == 'pickup':
        b = action[1]
        # preconditions assumed satisfied
        holding = b
        locs[b-1] = None  # remove from table (None denotes held)
    elif act == 'putdown':
        b = action[1]
        holding = None
        locs[b-1] = 0
        locked = frozenset(set(locked) | {b})
    elif act == 'unstack':
        b, y = action[1], action[2]
        holding = b
        locs[b-1] = None
        # y becomes clear automatically (handled by clear calculation)
    elif act == 'stack':
        b, y = action[1], action[2]
        holding = None
        locs[b-1] = y
    else:
        raise ValueError('unknown action')
    return (holding, tuple(locs), locked)

def possible_actions(state):
    holding, locs, locked = state
    clear = clear_blocks(locs)
    actions = []
    if holding is None:
        # pickup from table
        for b in clear:
            if locs[b-1] == 0 and b not in locked:
                actions.append(('pickup', b))
        # unstack
        for b in clear:
            y = locs[b-1]
            if y not in (0, None) and b not in locked:
                actions.append(('unstack', b, y))
    else:
        b = holding
        # putdown
        actions.append(('putdown', b))
        # stack onto any clear block
        for y in clear:
            if y != b:  # cannot stack onto itself
                actions.append(('stack', b, y))
    return actions

def state_key(state):
    return (state[0], state[1], state[2])

# ---------- BFS search ----------
def bfs():
    start = init_state
    queue = deque()
    queue.append((start, []))
    visited = set()
    visited.add(state_key(start))
    while queue:
        cur_state, plan = queue.popleft()
        if is_goal(cur_state):
            return plan
        for act in possible_actions(cur_state):
            nxt = apply_action(cur_state, act)
            key = state_key(nxt)
            if key in visited:
                continue
            visited.add(key)
            queue.append((nxt, plan + [act]))
    return None

plan = bfs()

# ---------- Output ----------
if plan is None:
    print("No plan")
else:
    name = lambda i: f"block{i}"
    for act in plan:
        if act[0] == 'pickup':
            print(f"(pickup {name(act[1])})")
        elif act[0] == 'putdown':
            print(f"(putdown {name(act[1])})")
        elif act[0] == 'unstack':
            print(f"(unstack {name(act[1])} {name(act[2])})")
        elif act[0] == 'stack':
            print(f"(stack {name(act[1])} {name(act[2])})")

#!/usr/bin/env python3
from collections import deque

# Blocks in fixed order
blocks = ['a','b','c','d','e','f','g','h','i','j','k']

# Initial locations
init_loc = {
    'a':'table','b':'a','c':'b','d':'table','e':'d',
    'f':None,          # held, so location is None
    'g':'table','h':'g','i':'h','j':'i','k':'j'
}
init_holding = 'f'  # we start holding block f

# Goal locations
goal_loc = {
    'a':'table','b':'a','c':'b','d':'table','e':'d',
    'f':'table','g':'f','h':'g','i':'h','j':'i','k':'j'
}
goal_holding = None

def state_key(holding, loc):
    """Create a hashable representation of a state."""
    return (holding, tuple(loc[b] for b in blocks))

def clear_blocks(loc):
    """Return a set of blocks that have nothing on top of them."""
    occupied = {v for v in loc.values() if v is not None}
    return {b for b in blocks if b not in occupied}

def is_goal(holding, loc):
    if holding != goal_holding:
        return False
    for b in blocks:
        if loc[b] != goal_loc[b]:
            return False
    return True

def bfs():
    start_key = state_key(init_holding, init_loc)
    queue = deque()
    queue.append( (init_holding, dict(init_loc), []) )
    visited = {start_key}
    while queue:
        holding, loc, plan = queue.popleft()
        if is_goal(holding, loc):
            return plan
        clear = clear_blocks(loc)

        if holding is None:
            # pickup from table
            for x in blocks:
                if loc[x]=='table' and x in clear:
                    new_loc = dict(loc)
                    new_loc[x] = None
                    new_holding = x
                    new_plan = plan + [('pickup', x)]
                    key = state_key(new_holding, new_loc)
                    if key not in visited:
                        visited.add(key)
                        queue.append( (new_holding, new_loc, new_plan) )
            # unstack
            for x in blocks:
                y = loc[x]
                if y is not None and x in clear:
                    new_loc = dict(loc)
                    new_loc[x] = None
                    new_holding = x
                    new_plan = plan + [('unstack', x, y)]
                    key = state_key(new_holding, new_loc)
                    if key not in visited:
                        visited.add(key)
                        queue.append( (new_holding, new_loc, new_plan) )
        else:
            x = holding
            # putdown
            new_loc = dict(loc)
            new_loc[x] = 'table'
            new_holding = None
            new_plan = plan + [('putdown', x)]
            key = state_key(new_holding, new_loc)
            if key not in visited:
                visited.add(key)
                queue.append( (new_holding, new_loc, new_plan) )
            # stack onto any clear block (not itself)
            for y in clear:
                if y == x:
                    continue
                new_loc = dict(loc)
                new_loc[x] = y
                new_holding = None
                new_plan = plan + [('stack', x, y)]
                key = state_key(new_holding, new_loc)
                if key not in visited:
                    visited.add(key)
                    queue.append( (new_holding, new_loc, new_plan) )
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
        return
    for act in plan:
        if act[0] in ('pickup','putdown'):
            print(f"({act[0]} {act[1]})")
        else:
            print(f"({act[0]} {act[1]} {act[2]})")

