#!/usr/bin/env python3
import sys
from collections import deque

# ----- Problem definition -----
blocks = [f"block{i}" for i in range(1, 15)]

# initial state: all on table, all clear, arm empty
def initial_state():
    on = {b: "table" for b in blocks}
    clear = set(blocks)
    holding = None
    return (frozenset(on.items()), frozenset(clear), holding, None)  # last_req = None

# goal configuration
goal_on = {
    "block1": "block9",
    "block9": "table",
    "block2": "table",
    "block11": "block2",
    "block12": "block11",
    "block13": "block12",
    "block3": "block13",
    "block7": "table",
    "block4": "block7",
    "block6": "table",
    "block14": "block6",
    "block5": "table",
    "block10": "block5",
    "block8": "table",
}
goal_clear = {"block1", "block3", "block4", "block14", "block10", "block8", "block9", "block2", "block7", "block6", "block5"}

def is_goal(state):
    on_items, clear_set, holding, _ = state
    if holding is not None:
        return False
    on = dict(on_items)
    if any(on[b] != goal_on.get(b, "table") for b in blocks):
        return False
    if set(clear_set) != goal_clear:
        return False
    return True

# ----- Action generation -----
def possible_actions(state):
    on_items, clear_set, holding, req = state
    on = dict(on_items)
    clear = set(clear_set)
    actions = []

    # helper to respect the extra constraint
    def allowed(block):
        if req is None:
            return True
        return block in req

    # pickup X (from table)
    if holding is None:
        for b in blocks:
            if on[b] == "table" and b in clear and allowed(b):
                actions.append(("pickup", b, None))
    # unstack X Y
    if holding is None:
        for b in blocks:
            if b in clear and on[b] != "table":
                y = on[b]
                if allowed(b):
                    actions.append(("unstack", b, y))
    # putdown X (to table)
    if holding is not None:
        b = holding
        if allowed(b):
            actions.append(("putdown", b, None))
    # stack X Y
    if holding is not None:
        b = holding
        for y in blocks:
            if y in clear and y != b and allowed(b):
                actions.append(("stack", b, y))
    return actions

def apply(state, action):
    on_items, clear_set, holding, req = state
    on = dict(on_items)
    clear = set(clear_set)
    act, x, y = action
    new_req = None

    if act == "pickup":
        # pre: arm empty, x clear, on table
        holding = x
        clear.remove(x)
        # no change to on
    elif act == "unstack":
        # pre: arm empty, x clear, on x = y
        holding = x
        clear.remove(x)
        clear.add(y)          # y becomes clear after removing x
        on[x] = None          # temporarily not on anything (held)
    elif act == "putdown":
        # pre: holding x
        holding = None
        clear.add(x)
        on[x] = "table"
    elif act == "stack":
        # pre: holding x, y clear
        holding = None
        clear.add(x)
        clear.remove(y)
        on[x] = y
    else:
        raise ValueError

    # enforce extra constraint: after moving block1 and arm becomes empty, next move must involve block2 or block3
    if act in ("putdown", "stack") and x == "block1":
        new_req = {"block2", "block3"}
    else:
        new_req = None

    return (frozenset(on.items()), frozenset(clear), holding, new_req)

# ----- Search (BFS) -----
def bfs():
    start = initial_state()
    queue = deque()
    queue.append((start, []))
    visited = set()
    visited.add(start)

    while queue:
        state, path = queue.popleft()
        if is_goal(state):
            return path
        for act in possible_actions(state):
            nxt = apply(state, act)
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, path + [act]))
    return None

def format_action(act):
    name, x, y = act
    if name in ("pickup", "putdown"):
        return f"({name} {x})"
    else:
        return f"({name} {x} {y})"

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for a in plan:
            print(format_action(a))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import collections

# ----- data ---------------------------------------------------------

blocks = [f'block{i}' for i in range(1, 15)]

# initial configuration
init_on = {
    'block3': 'table',
    'block14': 'block3',
    'block7': 'block14',
    'block11': 'block7',
    'block10': 'table',
    'block12': 'block10',
    'block5': 'block12',
    'block6': 'block5',
    'block8': 'block6',
    'block4': 'block8',
    'block9': 'block4',
    'block13': 'block9',
    'block2': 'block13',
    'block1': 'block2',
}

# goal configuration
goal_on = {
    'block14': 'table',
    'block4': 'block14',
    'block1': 'block4',
    'block11': 'table',
    'block5': 'block11',
    'block10': 'block5',
    'block6': 'block10',
    'block12': 'block6',
    'block3': 'block12',
    'block7': 'block3',
    'block13': 'block7',
    'block8': 'block13',
    'block9': 'block8',
    'block2': 'block9',
}

# ----- helper functions ----------------------------------------------

def clear_blocks(on):
    """Return a set of blocks that have nothing on top of them."""
    occupied = {v for v in on.values() if v != 'table' and v is not None}
    return {b for b in blocks if b not in occupied}

def state_key(on, holding, moved1):
    """Hashable representation of a state."""
    items = tuple(sorted((b, on[b]) for b in blocks))
    return (items, holding, moved1)

def is_goal(on, holding):
    if holding is not None:
        return False
    for b in blocks:
        if on[b] != goal_on[b]:
            return False
    return True

# ----- action generation ---------------------------------------------

def possible_actions(on, holding, moved1):
    """Yield (action_tuple, description) respecting the extra constraint."""
    clear = clear_blocks(on)

    # actions when hand empty
    if holding is None:
        # pickup from table
        for b in blocks:
            if on[b] == 'table' and b in clear:
                if b == 'block5' and not moved1:
                    continue
                yield (('pickup', b), f'(pickup {b})')
        # unstack
        for b in blocks:
            sup = on[b]
            if sup != 'table' and sup is not None and b in clear:
                if b == 'block5' and not moved1:
                    continue
                yield (('unstack', b, sup), f'(unstack {b} {sup})')
    else:
        b = holding
        # putdown
        yield (('putdown', b), f'(putdown {b})')
        # stack onto any clear block
        for c in clear:
            # cannot stack onto itself
            if c == b:
                continue
            yield (('stack', b, c), f'(stack {b} {c})')

# ----- state transition ----------------------------------------------

def apply(action, on, holding):
    """Return new (on, holding) after performing action."""
    new_on = on.copy()
    new_holding = holding

    if action[0] == 'pickup':
        b = action[1]
        new_holding = b
        new_on[b] = None
    elif action[0] == 'unstack':
        b, sup = action[1], action[2]
        new_holding = b
        new_on[b] = None
    elif action[0] == 'putdown':
        b = action[1]
        new_holding = None
        new_on[b] = 'table'
    elif action[0] == 'stack':
        b, sup = action[1], action[2]
        new_holding = None
        new_on[b] = sup
    else:
        raise ValueError('unknown action')
    return new_on, new_holding

# ----- BFS search ----------------------------------------------------

def bfs():
    start_on = init_on.copy()
    start_holding = None
    start_moved1 = False

    start_key = state_key(start_on, start_holding, start_moved1)
    queue = collections.deque()
    queue.append( (start_on, start_holding, start_moved1, []) )
    visited = {start_key}

    while queue:
        on, holding, moved1, plan = queue.popleft()

        if is_goal(on, holding):
            return plan

        for act, txt in possible_actions(on, holding, moved1):
            # enforce extra ordering constraint
            new_moved1 = moved1
            if act[0] in ('pickup', 'unstack') and act[1] == 'block1':
                new_moved1 = True

            new_on, new_holding = apply(act, on, holding)
            key = state_key(new_on, new_holding, new_moved1)
            if key in visited:
                continue
            visited.add(key)
            queue.append( (new_on, new_holding, new_moved1, plan + [txt]) )
    return None

# ----- main ----------------------------------------------------------

def main():
    plan = bfs()
    if plan is None:
        print('No plan')
    else:
        for line in plan:
            print(line)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import collections

# Blocks are numbered 1..7
BLOCKS = list(range(1, 8))

# Initial configuration: mapping block -> support ('table' or another block)
init_pos = {
    1: 6,
    2: 'table',
    3: 'table',
    4: 'table',
    5: 'table',
    6: 'table',
    7: 4,
}
init_holding = None
init_pending = False  # need to move a multiple of 5 next?

# Goal configuration
goal_pos = {
    1: 'table',
    2: 'table',
    3: 5,
    4: 'table',
    5: 'table',
    6: 4,
    7: 6,
}
goal_holding = None
goal_pending = False

def is_clear(pos, block):
    """A block is clear if no other block is on it."""
    return all(sup != block for sup in pos.values())

def state_key(pos, holding, pending):
    """Hashable representation of a state."""
    items = tuple(sorted((b, pos[b]) for b in BLOCKS))
    return (items, holding, pending)

def generate_actions(pos, holding, pending):
    """Yield (action_str, new_pos, new_holding, new_pending)."""
    # Helper to test pending constraint
    def allowed_move(moved):
        if pending:
            return moved % 5 == 0
        return True

    # If arm empty: can pickup from table or unstack
    if holding is None:
        # pickup from table
        for b in BLOCKS:
            if pos[b] == 'table' and is_clear(pos, b):
                if not allowed_move(b):
                    continue
                new_pos = pos.copy()
                new_holding = b
                new_pending = (b % 3 == 0)
                act = f"(pickup block{b})"
                yield act, new_pos, new_holding, new_pending
        # unstack from another block
        for b in BLOCKS:
            sup = pos[b]
            if sup != 'table' and is_clear(pos, b):
                if not allowed_move(b):
                    continue
                new_pos = pos.copy()
                new_holding = b
                new_pending = (b % 3 == 0)
                act = f"(unstack block{b} block{sup})"
                yield act, new_pos, new_holding, new_pending
    else:
        # holding a block: can putdown on table
        b = holding
        if not pending or (b % 5 == 0):
            new_pos = pos.copy()
            new_pos[b] = 'table'
            new_holding = None
            new_pending = (b % 3 == 0)
            act = f"(putdown block{b})"
            yield act, new_pos, new_holding, new_pending
        # stack onto a clear block
        for target in BLOCKS:
            if target == b:
                continue
            if is_clear(pos, target):
                if not allowed_move(b):
                    continue
                new_pos = pos.copy()
                new_pos[b] = target
                new_holding = None
                new_pending = (b % 3 == 0)
                act = f"(stack block{b} block{target})"
                yield act, new_pos, new_holding, new_pending

def is_goal(pos, holding, pending):
    return pos == goal_pos and holding == goal_holding and pending == goal_pending

def bfs():
    start_key = state_key(init_pos, init_holding, init_pending)
    queue = collections.deque()
    queue.append((init_pos, init_holding, init_pending, []))
    visited = {start_key}
    while queue:
        pos, holding, pending, path = queue.popleft()
        if is_goal(pos, holding, pending):
            return path
        for act, npos, nholding, npending in generate_actions(pos, holding, pending):
            key = state_key(npos, nholding, npending)
            if key in visited:
                continue
            visited.add(key)
            queue.append((npos, nholding, npending, path + [act]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for line in plan:
            print(line)

if __name__ == "__main__":
    main()

