import collections

# Define blocks
blocks = [f"block{i}" for i in range(1, 9)]

# Initial support mapping
init_support = {
    "block2": "table",
    "block6": "block2",
    "block4": "block6",
    "block3": "table",
    "block1": "table",
    "block5": "block1",
    "block7": "block5",
    "block8": "block7",
}
# Ensure all blocks have an entry
for b in blocks:
    init_support.setdefault(b, None)

# Goal support mapping
goal_support = {
    "block5": "table",
    "block6": "block5",
    "block4": "table",
    "block1": "table",
    "block3": "table",
    "block7": "table",
    "block2": "table",
    "block8": "table",
}
for b in blocks:
    goal_support.setdefault(b, None)

def state_key(holding, support):
    """Create a hashable representation of a state."""
    return (holding, tuple(support[b] for b in blocks))

def is_clear(support, block):
    """A block is clear if no other block is on it."""
    return all(support[other] != block for other in blocks)

def successors(state):
    """Generate (action_str, new_state) pairs."""
    holding, support = state
    actions = []

    # Helper to copy support dict
    def copy_support():
        return {b: support[b] for b in blocks}

    if holding is None:
        # pickup from table
        for b in blocks:
            if is_clear(support, b) and support[b] == "table":
                new_support = copy_support()
                new_support[b] = None
                actions.append(
                    (f"(pickup {b})", (b, new_support))
                )
        # unstack clear block from another block
        for b in blocks:
            if is_clear(support, b) and support[b] not in (None, "table"):
                below = support[b]
                new_support = copy_support()
                new_support[b] = None
                actions.append(
                    (f"(unstack {b} {below})", (b, new_support))
                )
    else:
        # putdown held block on table
        new_support = copy_support()
        new_support[holding] = "table"
        actions.append(
            (f"(putdown {holding})", (None, new_support))
        )
        # stack held block onto any clear block (except itself)
        for b in blocks:
            if b != holding and is_clear(support, b):
                new_support = copy_support()
                new_support[holding] = b
                actions.append(
                    (f"(stack {holding} {b})", (None, new_support))
                )
    return actions

def is_goal(state):
    holding, support = state
    if holding is not None:
        return False
    return all(support[b] == goal_support[b] for b in blocks)

def bfs():
    start = (None, init_support)
    start_key = state_key(*start)
    queue = collections.deque([start])
    visited = {start_key: None}
    action_from = {}

    while queue:
        current = queue.popleft()
        if is_goal(current):
            # reconstruct path
            path = []
            key = state_key(*current)
            while visited[key] is not None:
                prev_key, act = visited[key]
                path.append(act)
                key = prev_key
            return list(reversed(path))
        for act_str, new_state in successors(current):
            new_key = state_key(*new_state)
            if new_key not in visited:
                visited[new_key] = (state_key(*current), act_str)
                queue.append(new_state)
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for line in plan:
            print(line)

if __name__ == "__main__":
    main()

import heapq
from collections import defaultdict

# Blocks are numbered 1..12
N = 12

# Initial positions: 0 = table, otherwise block number it is on
init_pos = [0] * (N + 1)
# Table blocks: 7,9,4,6,12,8,2,3
for b in [7, 9, 4, 6, 12, 8, 2, 3]:
    init_pos[b] = 0
# Stacks
init_pos[5] = 4   # 5 on 4
init_pos[11] = 5  # 11 on 5
init_pos[1] = 10  # 1 on 10
init_pos[10] = 0  # 10 on table

init_hand = None  # empty

# Goal positions (excluding block12 which must be held at the end)
goal_pos = [0] * (N + 1)
goal_pos[9] = 0
goal_pos[11] = 9
goal_pos[3] = 11

goal_pos[4] = 0
goal_pos[6] = 4
goal_pos[10] = 6
goal_pos[1] = 10
goal_pos[7] = 1
goal_pos[5] = 7
goal_pos[8] = 5
goal_pos[2] = 8

# Helper to compute clear blocks from positions
def compute_clear(pos):
    occupied = set(pos[1:]) - {0}
    return {i for i in range(1, N + 1) if i not in occupied}

def is_goal(hand, pos):
    if hand != 12:
        return False
    for b in range(1, N + 1):
        if b == 12:
            continue
        if pos[b] != goal_pos[b]:
            return False
    return True

def heuristic(hand, pos):
    h = 0
    if hand != 12:
        h += 1
    for b in range(1, N + 1):
        if b == 12:
            continue
        if pos[b] != goal_pos[b]:
            h += 1
    return h

def encode_state(hand, pos):
    return (hand, tuple(pos[1:]))

def successors(hand, pos):
    clear = compute_clear(pos)
    succ = []
    # hand empty: can pickup or unstack
    if hand is None:
        for x in clear:
            if pos[x] == 0:  # on table
                new_pos = pos[:]
                new_pos[x] = -1  # -1 means held (removed from table)
                succ.append( (x, None, 'pickup', new_pos) )
            else:
                y = pos[x]
                new_pos = pos[:]
                new_pos[x] = -1
                succ.append( (x, y, 'unstack', new_pos) )
    else:
        x = hand
        # putdown
        new_pos = pos[:]
        new_pos[x] = 0
        succ.append( (x, None, 'putdown', new_pos) )
        # stack onto any clear block (except itself)
        for y in clear:
            if y == x:
                continue
            new_pos = pos[:]
            new_pos[x] = y
            succ.append( (x, y, 'stack', new_pos) )
    return succ

def a_star():
    start = (init_hand, init_pos[:])
    start_key = encode_state(*start)
    frontier = [(heuristic(*start), 0, start_key, [], start)]
    heapq.heapify(frontier)
    visited = {start_key: 0}
    while frontier:
        est, g, key, path, (hand, pos) = heapq.heappop(frontier)
        if is_goal(hand, pos):
            return path
        for x, y, act, new_pos in successors(hand, pos):
            new_hand = None if act in ('pickup', 'unstack') else x
            # normalize held block representation: we used -1 in pos to indicate removed
            norm_pos = new_pos[:]
            if act in ('pickup', 'unstack'):
                norm_pos[x] = -1
            elif act in ('putdown', 'stack'):
                # already set correctly
                pass
            new_key = encode_state(new_hand, norm_pos)
            new_g = g + 1
            if visited.get(new_key, float('inf')) <= new_g:
                continue
            visited[new_key] = new_g
            # build action string
            if act == 'pickup':
                act_str = f"(pickup block{x})"
            elif act == 'putdown':
                act_str = f"(putdown block{x})"
            elif act == 'unstack':
                act_str = f"(unstack block{x} block{y})"
            else:  # stack
                act_str = f"(stack block{x} block{y})"
            heapq.heappush(frontier, (new_g + heuristic(new_hand, norm_pos), new_g, new_key, path + [act_str], (new_hand, norm_pos)))
    return None

plan = a_star()
if plan is None:
    print("No plan")
else:
    for line in plan:
        print(line)

#!/usr/bin/env python3
import collections
import sys

# ----- problem definition -----
blocks = [f'block{i}' for i in range(1, 16)]

# initial configuration: mapping block -> what it is on (0 = table)
init_on = {
    'block6': 0, 'block3': 'block6', 'block5': 'block3',
    'block11': 0,
    'block14': 0,
    'block8': 'block14', 'block7': 'block8', 'block9': 'block7',
    'block4': 'block9', 'block15': 'block4', 'block12': 'block15',
    'block2': 'block12', 'block13': 'block2', 'block10': 'block13',
    'block1': 0
}

# goal configuration
goal_on = {
    'block8': 0, 'block7': 'block8', 'block12': 'block7',
    'block5': 'block12', 'block13': 'block5',
    'block15': 0, 'block4': 'block15',
    'block3': 0, 'block11': 'block3', 'block2': 'block11',
    'block9': 'block2', 'block14': 'block9', 'block10': 'block14',
    'block6': 'block10', 'block1': 'block6'
}

# ----- helper functions -----
def clear_blocks(on_map):
    """Return set of blocks that have nothing on top."""
    occupied = {v for v in on_map.values() if v != 0}
    return {b for b in blocks if b not in occupied}

def stacks_count(on_map):
    """Number of blocks directly on the table."""
    return sum(1 for b in blocks if on_map[b] == 0)

def state_key(on_map, holding):
    """Immutable representation for visited set."""
    return (tuple(sorted(on_map.items())), holding)

def is_goal(on_map, holding):
    if holding is not None:
        return False
    for b in blocks:
        if on_map.get(b, None) != goal_on.get(b, None):
            return False
    return True

# ----- actions -----
def successors(state):
    on_map, holding = state
    clear = clear_blocks(on_map)
    res = []

    # pickup from table
    if holding is None:
        for b in clear:
            if on_map[b] == 0:
                new_on = on_map.copy()
                new_on[b] = None  # removed from table
                if stacks_count(new_on) == 4:
                    res.append(((new_on, b), f'(pickup {b})'))

    # unstack X Y
    if holding is None:
        for b in clear:
            y = on_map[b]
            if y != 0 and y is not None:
                new_on = on_map.copy()
                new_on[b] = None
                if stacks_count(new_on) == 4:
                    res.append(((new_on, b), f'(unstack {b} {y})'))

    # putdown X
    if holding is not None:
        new_on = on_map.copy()
        new_on[holding] = 0
        if stacks_count(new_on) == 4:
            res.append(((new_on, None), f'(putdown {holding})'))

    # stack X Y
    if holding is not None:
        for y in clear:
            if y == holding:
                continue
            new_on = on_map.copy()
            new_on[holding] = y
            if stacks_count(new_on) == 4:
                res.append(((new_on, None), f'(stack {holding} {y})'))

    return res

# ----- search -----
def bfs():
    start_on = init_on.copy()
    start_state = (start_on, None)
    if stacks_count(start_on) != 4:
        # initial state violates the "exactly 4 stacks" rule after first move,
        # but the rule applies only after we start moving, so we allow it.
        pass
    frontier = collections.deque()
    frontier.append((start_state, []))
    visited = set()
    visited.add(state_key(*start_state))

    while frontier:
        (on_map, holding), path = frontier.popleft()
        if is_goal(on_map, holding):
            return path
        for (new_state, act) in successors((on_map, holding)):
            key = state_key(*new_state)
            if key in visited:
                continue
            visited.add(key)
