import collections

# Blocks
blocks = ['a', 'b', 'c', 'd', 'e']

# Initial configuration: two towers.
# Tower 1: a (table) -> c -> e
# Tower 2: b (table) -> d
initial_on = {
    'a': 'table',
    'c': 'a',
    'e': 'c',
    'b': 'table',
    'd': 'b',
}
initial_hand = None  # empty hand

# Goal configuration: e on table, d on e, c on d, b on c, a on b
goal_on = {
    'a': 'b',
    'b': 'c',
    'c': 'd',
    'd': 'e',
    'e': 'table',
}
goal_hand = None  # hand empty at the end

def clear_blocks(on):
    """Return a set of blocks that have nothing on top of them."""
    occupied = {v for v in on.values() if v != 'table' and v is not None}
    return {b for b in blocks if b not in occupied}

def serialize(state):
    hand, on = state
    # hand as '_' for None
    hand_key = '_' if hand is None else hand
    # order blocks alphabetically for deterministic key
    on_items = tuple((b, on[b]) for b in sorted(blocks))
    return (hand_key, on_items)

def is_goal(state):
    hand, on = state
    if hand != goal_hand:
        return False
    for b in blocks:
        if on[b] != goal_on[b]:
            return False
    return True

def successors(state):
    hand, on = state
    clear = clear_blocks(on)
    succ = []

    if hand is None:
        # pickup from table
        for x in clear:
            if on[x] == 'table':
                new_on = on.copy()
                new_on[x] = None  # held
                succ.append(((x), (new_on, x), f"(pickup block{x})"))
        # unstack
        for x in clear:
            y = on[x]
            if y not in (None, 'table'):
                new_on = on.copy()
                new_on[x] = None
                succ.append(((x), (new_on, x), f"(unstack block{x} block{y})"))
    else:
        x = hand
        # putdown on table
        new_on = on.copy()
        new_on[x] = 'table'
        succ.append((None, (new_on, None), f"(putdown block{x})"))
        # stack onto any clear block (except itself)
        for y in clear:
            if y == x:
                continue
            new_on = on.copy()
            new_on[x] = y
            succ.append((None, (new_on, None), f"(stack block{x} block{y})"))
    return succ

def bfs():
    start = (initial_hand, initial_on)
    queue = collections.deque()
    queue.append((start, []))
    visited = set()
    visited.add(serialize(start))

    while queue:
        (hand, on), plan = queue.popleft()
        if is_goal((hand, on)):
            return plan
        for _, (new_state, new_hand), action in successors((hand, on)):
            state = (new_hand, new_state)
            key = serialize(state)
            if key in visited:
                continue
            visited.add(key)
            queue.append((state, plan + [action]))
    return None

plan = bfs()
if plan is None:
    print("No plan")
else:
    for act in plan:
        print(act)

