import heapq
from collections import deque

# -----------------------------
# Problem definition
# -----------------------------
blocks = [str(i) for i in range(1, 15)]

# initial configuration: mapping block -> what it is on (None = table)
init_on = {
    # Stack A
    "3": None, "9": "3", "4": "9", "2": "4", "14": "2", "12": "14", "7": "12",
    # Stack B
    "11": None, "8": "11", "1": "8", "6": "1", "10": "6", "13": "10",
    # Single block
    "5": None,
}
# ensure every block appears
for b in blocks:
    init_on.setdefault(b, None)

# goal configuration
goal_on = {b: None for b in blocks}
goal_on.update({
    "8": "6",
    "14": "11",
    "7": "14",
    "3": "9",
})
# blocks that must be on table in goal (explicit for clarity)
for b in ["6", "5", "12", "1", "11", "4", "9", "13", "2", "10"]:
    goal_on[b] = None

# -----------------------------
# Helper functions
# -----------------------------
def clear_blocks(on):
    """Return a set of blocks that have nothing on top of them."""
    occupied = {v for v in on.values() if v is not None}
    return {b for b in blocks if b not in occupied}

def stack_heights(on):
    """Return a dict block->height of the stack whose base is that block (table)."""
    child = {}
    for b, sup in on.items():
        if sup is not None:
            child[sup] = b
    heights = {}
    for b in blocks:
        if on[b] is None:  # base on table
            h = 1
            cur = b
            while cur in child:
                cur = child[cur]
                h += 1
            heights[b] = h
    return heights

def max_stack_height(on):
    return max(stack_heights(on).values(), default=0)

def is_goal(on):
    return all(on[b] == goal_on[b] for b in blocks)

def state_key(holding, on):
    """Immutable representation for visited set."""
    # tuple of (holding or None, tuple of (block, support) sorted)
    items = tuple(sorted(on.items()))
    return (holding, items)

# -----------------------------
# Action generation
# -----------------------------
def successors(state, moved):
    """Generate (new_state, action_str) from given state.
    `moved` is True if at least one action has already been taken (to enforce height limit)."""
    holding, on = state
    clear = clear_blocks(on)
    succ = []

    # ----- arm empty -----
    if holding is None:
        # pickup from table
        for b in clear:
            if on[b] is None:
                new_on = on.copy()
                new_on[b] = None  # will be held, not on anything
                new_state = (b, new_on)
                if not moved or max_stack_height(new_on) <= 5:
                    succ.append((new_state, f"(pickup block{b})"))
        # unstack
        for b in clear:
            sup = on[b]
            if sup is not None:
                new_on = on.copy()
                new_on[b] = None
                new_state = (b, new_on)
                if not moved or max_stack_height(new_on) <= 5:
                    succ.append((new_state, f"(unstack block{b} block{sup})"))
    else:
        # ----- holding a block -----
        # putdown on table
        new_on = on.copy()
        new_on[holding] = None
        new_state = (None, new_on)
        if not moved or max_stack_height(new_on) <= 5:
            succ.append((new_state, f"(putdown block{holding})"))
        # stack onto a clear block
        for b in clear:
            if b == holding:
                continue
            new_on = on.copy()
            new_on[holding] = b
            new_state = (None, new_on)
            if not moved or max_stack_height(new_on) <= 5:
                succ.append((new_state, f"(stack block{holding} block{b})"))
    return succ

# -----------------------------
# A* search
# -----------------------------
def heuristic(on):
    """Number of blocks not on their goal support."""
    return sum(1 for b in blocks if on[b] != goal_on[b])

def a_star():
    start = (None, init_on)
    frontier = []
    heapq.heappush(frontier, (heuristic(init_on), 0, start, [] , False))  # (f, g, state, path, moved)
    visited = set()
    while frontier:
        f, g, (holding, on), path, moved = heapq.heappop(frontier)
        key = state_key(holding, on)
        if key in visited:
            continue
        visited.add(key)

        if is_goal(on) and holding is None:
            return path

        for (new_state, act) in successors((holding, on), moved):
            new_holding, new_on = new_state
            new_path = path + [act]
            new_g = g + 1
            new_f = new_g + heuristic(new_on)
            heapq.heappush(frontier, (new_f, new_g, new_state, new_path, True))
    return None

# -----------------------------
# Main execution
# -----------------------------
def main():
    plan = a_star()
    if plan is None:
        print("No plan")
    else:
        for a in plan:
            print(a)

if __name__ == "__main__":
    main()

import heapq

# Define blocks
blocks = [f"block{i}" for i in range(1, 15)]

# Initial on mapping (support can be another block or 'table')
init_on = {
    "block11": "table", "block5": "table", "block3": "table", "block4": "table",
    "block12": "table", "block13": "table", "block10": "table", "block2": "table",
    "block1": "block5", "block6": "block1", "block9": "block6",
    "block14": "block4", "block8": "block12", "block7": "block13"
}

# Goal on mapping
goal_on = {
    "block14": "table", "block8": "table", "block1": "table", "block5": "table",
    "block7": "table", "block10": "table", "block12": "table", "block9": "table",
    "block3": "table", "block13": "table",
    "block2": "block7", "block4": "block10", "block11": "block3", "block6": "block13"
}

def state_key(on_map, holding):
    """Immutable representation for hashing."""
    items = tuple(sorted(on_map.items()))
    return (holding, items)

def is_clear(block, on_map, holding):
    """A block is clear if nothing is on it and it's not being held."""
    if holding == block:
        return False
    return block not in on_map.values()

def is_goal(on_map):
    return all(on_map.get(b, None) == goal_on[b] for b in goal_on)

def heuristic(on_map):
    """Number of blocks not in goal position."""
    return sum(1 for b, sup in goal_on.items() if on_map.get(b) != sup)

def successors(on_map, holding):
    succ = []
    # Helper to create new state dict copy
    def copy_on():
        return dict(on_map)

    # pickup X
    if holding is None:
        for b in blocks:
            if on_map.get(b) == "table" and is_clear(b, on_map, holding):
                new_on = copy_on()
                del new_on[b]  # block is now in hand, no support
                succ.append((f"(pickup {b})", new_on, b))
    # putdown X
    if holding is not None:
        b = holding
        new_on = copy_on()
        new_on[b] = "table"
        succ.append((f"(putdown {b})", new_on, None))
    # unstack X Y
    if holding is None:
        for b in blocks:
            sup = on_map.get(b)
            if sup and sup != "table" and is_clear(b, on_map, holding):
                # b is clear and on another block sup
                new_on = copy_on()
                del new_on[b]
                succ.append((f"(unstack {b} {sup})", new_on, b))
    # stack X Y
    if holding is not None:
        x = holding
        for y in blocks:
            if y == x:
                continue
            if is_clear(y, on_map, holding):
                new_on = copy_on()
                new_on[x] = y
                succ.append((f"(stack {x} {y})", new_on, None))
    return succ

def a_star():
    start_on = dict(init_on)
    start_holding = None
    start_key = state_key(start_on, start_holding)
    frontier = [(heuristic(start_on), 0, start_key, start_on, start_holding, [])]
    visited = {start_key: 0}
    while frontier:
        f, g, key, on_map, holding, path = heapq.heappop(frontier)
        if is_goal(on_map):
            return path
        for act, new_on, new_holding in successors(on_map, holding):
            new_key = state_key(new_on, new_holding)
            new_g = g + 1
            if new_key not in visited or new_g < visited[new_key]:
                visited[new_key] = new_g
                h = heuristic(new_on)
                heapq.heappush(frontier, (new_g + h, new_g, new_key, new_on, new_holding, path + [act]))
    return None

def main():
    plan = a_star()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(act)

if __name__ == "__main__":
    main()

