}

def clear_set(support):
    """Return set of blocks that have nothing on top of them."""
    occupied = {v for v in support.values() if v != 0}
    return {b for b in blocks if b not in occupied}

def state_key(support, holding):
    """Immutable representation for hashing."""
    # order by block number 1..9
    tup = tuple(support[b] for b in blocks)
    return (tup, holding)

def is_goal(support):
    return all(support[b] == goal_support[b] for b in blocks)

# ---------- Action generation ----------
def possible_actions(support, holding):
    clear = clear_set(support)
    actions = []

    if holding == 0:
        # can pickup from table
        for b in clear:
            if support[b] == 0:
                actions.append(('pickup', b, None))
        # can unstack
        for b in clear:
            if support[b] != 0:
                actions.append(('unstack', b, support[b]))
    else:
        # holding a block, can putdown
        actions.append(('putdown', holding, None))
        # can stack onto any clear block
        for b in clear:
            actions.append(('stack', holding, b))
    return actions

def apply_action(support, holding, action):
    typ, x, y = action
    new_support = support.copy()
    new_holding = holding
    if typ == 'pickup':
        new_holding = x
        new_support[x] = None  # temporarily not on anything
    elif typ == 'putdown':
        new_holding = 0
        new_support[x] = 0
    elif typ == 'unstack':
        new_holding = x
        new_support[x] = None
        # y becomes clear automatically (no need to store)
    elif typ == 'stack':
        new_holding = 0
        new_support[x] = y
    return new_support, new_holding

def action_str(action):
    typ, x, y = action
    if typ in ('pickup', 'putdown'):
        return f'({typ} block{x})'
    elif typ == 'unstack':
        return f'({typ} block{x} block{y})'
    elif typ == 'stack':
        return f'({typ} block{x} block{y})'
    else:
        raise ValueError

# ---------- BFS search ----------
def bfs():
    start_key = state_key(init_support, 0)
    queue = collections.deque([start_key])
    visited = {start_key: (None, None)}   # state_key -> (parent_key, action)

    while queue:
        cur_key = queue.popleft()
        cur_support_vals, cur_holding = cur_key
        cur_support = {b: cur_support_vals[i] for i, b in enumerate(blocks)}
        # clean None entries (means being held)
        for b in blocks:
            if cur_support[b] is None:
                cur_support[b] = 0  # placeholder, won't be used while held

        if is_goal(cur_support):
            # reconstruct path
            path = []
            while visited[cur_key][0] is not None:
                parent, act = visited[cur_key]
                path.append(act)
                cur_key = parent
            return list(reversed(path))
        for act in possible_actions(cur_support, cur_holding):
            new_support, new_holding = apply_action(cur_support, cur_holding, act)
            # clean None for held block
            for b in blocks:
                if new_support[b] is None:
                    new_support[b] = 0
            new_key = state_key(new_support, new_holding)
            if new_key not in visited:
                visited[new_key] = (cur_key, act)
                queue.append(new_key)
    return None

