def is_clear(b, on_dict, hand):
    """A block is clear if nothing is on it and it is not being held."""
    if hand == b:
        return False
    return b not in on_dict.values()

def serialize(state):
    hand, on = state
    hand_key = 0 if hand is None else hand
    on_items = tuple(sorted(on.items()))
    return (hand_key, on_items)

def goal_test(state):
    hand, on = state
    if hand != goal_hand:
        return False
    return on == goal_on

def successors(state):
    hand, on = state
    succ = []

    # Helper to create action string
    def act_str(action, *args):
        return '(' + action + ' ' + ' '.join(f'block{a}' for a in args) + ')'

    if hand is None:
        # pickup from table
        for b in blocks:
            if b in on and on[b] == 'table' and is_clear(b, on, hand):
                new_on = on.copy()
                del new_on[b]
                succ.append((act_str('pickup', b), (b, new_on)))
        # unstack
        for b in blocks:
            if b in on and on[b] != 'table' and is_clear(b, on, hand):
                y = on[b]
                new_on = on.copy()
                del new_on[b]
                succ.append((act_str('unstack', b, y), (b, new_on)))
    else:
        # hand holds block X
        x = hand
        # putdown
        new_on = on.copy()
        new_on[x] = 'table'
        succ.append((act_str('putdown', x), (None, new_on)))
        # stack onto any clear block
        for y in blocks:
            if y == x:
                continue
            if y in on and is_clear(y, on, hand):
                new_on = on.copy()
                new_on[x] = y
                succ.append((act_str('stack', x, y), (None, new_on)))
    return succ

def bfs():
    start = (initial_hand, initial_on)
    frontier = deque()
    frontier.append(start)
    came_from = {serialize(start): (None, None)}  # state -> (prev_state, action)
    while frontier:
        current = frontier.popleft()
        if goal_test(current):
            # reconstruct path
            actions = []
            key = serialize(current)
            while came_from[key][0] is not None:
                prev_key, action = came_from[key]
                actions.append(action)
                key = prev_key
            actions.reverse()
            return actions
        for action, nxt in successors(current):
            sk = serialize(nxt)
            if sk not in came_from:
                came_from[sk] = (serialize(current), action)
                frontier.append(nxt)
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
