from collections import deque

# Blocks are identified by integers 1,2,3
BLOCKS = (1, 2, 3)

def state_key(stacks, held):
    """Create a hashable representation of a state."""
    # Sort stacks to make order irrelevant (except internal order)
    sorted_stacks = tuple(sorted(tuple(s) for s in stacks))
    return (sorted_stacks, held)

def stack_sums_ok(stacks):
    """Check the additional constraint: sum of numbers in each stack ≤ 5."""
    return all(sum(s) <= 5 for s in stacks)

def is_goal(stacks, held):
    """Goal: one stack (3,2,1) bottom‑to‑top and arm empty."""
    return held is None and any(tuple(s) == (3, 2, 1) for s in stacks)

def possible_actions(stacks, held):
    """Generate all legal actions from the current state."""
    actions = []

    # Helper to find stack index containing a block
    def find_block(b):
        for i, s in enumerate(stacks):
            if b in s:
                return i, s.index(b)
        return None, None

    if held is None:  # arm empty: can pickup or unstack
        for i, s in enumerate(stacks):
            top = s[-1]
            # pickup: block is alone on table
            if len(s) == 1:
                actions.append(('pickup', top, None))
            # unstack: any block that is on top of another
            if len(s) >= 2:
                # top block can be unstacked from the one below it
                below = s[-2]
                actions.append(('unstack', top, below))
    else:  # holding a block: can putdown or stack
        # putdown onto table
        actions.append(('putdown', held, None))
        # stack onto any clear block (i.e., top of a stack)
        for i, s in enumerate(stacks):
            clear = s[-1]
            actions.append(('stack', held, clear))

    return actions

def apply_action(stacks, held, action):
    """Return new (stacks, held) after performing the action."""
    act, x, y = action
    new_stacks = [list(s) for s in stacks]  # mutable copy
    new_held = held

    if act == 'pickup':
        # x is alone on table
        for i, s in enumerate(new_stacks):
            if s == [x]:
                new_held = x
                del new_stacks[i]
                break

    elif act == 'unstack':
        # x is on top of y in some stack
        for i, s in enumerate(new_stacks):
            if len(s) >= 2 and s[-2] == y and s[-1] == x:
                new_held = x
                new_stacks[i] = s[:-1]  # remove top block
                if not new_stacks[i]:
                    del new_stacks[i]
                break

    elif act == 'putdown':
        # place held block on table as a new stack
        new_stacks.append([x])
        new_held = None

    elif act == 'stack':
        # place held block onto clear block y
        for i, s in enumerate(new_stacks):
            if s[-1] == y:
                new_stacks[i].append(x)
                new_held = None
                break

    # Convert back to tuple-of-tuples for consistency
    new_stacks = tuple(tuple(s) for s in new_stacks)
    return new_stacks, new_held

def format_action(action):
    act, x, y = action
    name = {1: 'block1', 2: 'block2', 3: 'block3'}[x]
    if act in ('pickup', 'putdown'):
        return f'({act} {name})'
    else:
        name_y = {1: 'block1', 2: 'block2', 3: 'block3'}[y]
        return f'({act} {name} {name_y})'

def bfs():
    # Initial state: block3 on table, block2 with block1 on top, arm empty
    init_stacks = ((3,), (2, 1))
    init_held = None
    start_key = state_key(init_stacks, init_held)

    queue = deque()
    queue.append((init_stacks, init_held, []))
    visited = {start_key}

    while queue:
        stacks, held, plan = queue.popleft()
        if is_goal(stacks, held):
            return plan

        for action in possible_actions(stacks, held):
            new_stacks, new_held = apply_action(stacks, held, action)
            if not stack_sums_ok(new_stacks):
                continue
            key = state_key(new_stacks, new_held)
            if key in visited:
                continue
            visited.add(key)
            queue.append((new_stacks, new_held, plan + [action]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(format_action(act))

if __name__ == "__main__":
    main()

import collections

# Block indices: 0->block1, 1->block2, ..., 5->block6
NUM_BLOCKS = 6
TABLE = -1
