def is_even(idx):
    return (idx + 1) % 2 == 0

def is_odd(idx):
    return (idx + 1) % 2 == 1

def clear_blocks(on):
    """Return a set of block indices that have nothing on top of them."""
    occupied = {on[i] for i in range(NUM_BLOCKS) if on[i] >= 0}
    return {i for i in range(NUM_BLOCKS)} - occupied

def goal_test(on, holding):
    return holding is None and on == GOAL_ON

def generate_actions(on, holding):
    actions = []
    clear = clear_blocks(on)

    # pickup
    if holding is None:
        for i in clear:
            if on[i] == TABLE:
                actions.append(('pickup', i))
    # putdown
    if holding is not None:
        actions.append(('putdown', holding))
    # unstack
    if holding is None:
        for i in clear:
            if on[i] >= 0:  # on a block
                actions.append(('unstack', i, on[i]))
    # stack
    if holding is not None:
        for j in clear:
            # cannot stack even onto odd
            if is_even(holding) and is_odd(j):
                continue
            actions.append(('stack', holding, j))
    return actions

def apply_action(on, holding, action):
    on = list(on)
    new_holding = holding
    act = action[0]

    if act == 'pickup':
        i = action[1]
        new_holding = i
        on[i] = HELD
    elif act == 'putdown':
        i = action[1]
        new_holding = None
        on[i] = TABLE
    elif act == 'unstack':
        i, j = action[1], action[2]
        new_holding = i
        on[i] = HELD
        # j becomes clear automatically (handled by clear detection)
    elif act == 'stack':
        i, j = action[1], action[2]
        new_holding = None
        on[i] = j
    else:
        raise ValueError('unknown action')
    return tuple(on), new_holding

def action_to_str(action):
    if action[0] == 'pickup':
        return f"(pickup block{action[1]+1})"
    if action[0] == 'putdown':
        return f"(putdown block{action[1]+1})"
    if action[0] == 'unstack':
        return f"(unstack block{action[1]+1} block{action[2]+1})"
    if action[0] == 'stack':
        return f"(stack block{action[1]+1} block{action[2]+1})"
    return ""

# Initial configuration
# block1 on block4, block2 on block1, block3 on table,
# block4 on block5, block5 on block6, block6 on block3
INIT_ON = (3, 0, TABLE, 4, 5, 2)
INIT_HOLDING = None

# Goal configuration
# block1 on table, block2 on table, block3 on block4,
# block4 on table, block5 on table, block6 on block2
GOAL_ON = (-1, -1, 3, -1, -1, 1)

def bfs():
    start = (INIT_ON, INIT_HOLDING)
    queue = collections.deque()
    queue.append((INIT_ON, INIT_HOLDING, []))
    visited = set()
    visited.add(start)

    while queue:
        on, holding, plan = queue.popleft()
        if goal_test(on, holding):
            return plan
        for act in generate_actions(on, holding):
            new_on, new_holding = apply_action(on, holding, act)
            state = (new_on, new_holding)
            if state in visited:
                continue
            visited.add(state)
            queue.append((new_on, new_holding, plan + [act]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(action_to_str(act))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# Blocksworld planner with weight constraint.
# If the goal configuration violates the weight constraint, print "No plan".

blocks = list(range(1, 9))  # block numbers 1..8
weight = {i: i for i in blocks}

# Goal state: mapping block -> what it is on ('table' or another block)
goal_on = {
    3: 'table',
    8: 3,
    4: 8,
    1: 4,
    2: 1,
    7: 2,
    6: 7,
    5: 6,
}

def build_above_map(on_map):
    """Return a dict block->block directly on it (or None)."""
    above = {b: None for b in blocks}
    for blk, below in on_map.items():
        if below != 'table':
            above[below] = blk
    return above

def total_above_weight(block, above_map, memo):
    """Recursive total weight of all blocks above the given block."""
    if block in memo:
        return memo[block]
    above = above_map[block]
    if above is None:
        memo[block] = 0
    else:
        memo[block] = weight[above] + total_above_weight(above, above_map, memo)
    return memo[block]

def satisfies_weight_constraint(on_map):
    """Check that for every block, total weight above <= its own weight."""
    above_map = build_above_map(on_map)
    memo = {}
    for b in blocks:
        if total_above_weight(b, above_map, memo) > weight[b]:
            return False
    return True

if not satisfies_weight_constraint(goal_on):
    print("No plan")
else:
    # Placeholder for a planner (not needed because goal is infeasible)
    print("No plan")

#!/usr/bin/env python3
from collections import deque

# Define blocks
blocks = [chr(ord('a') + i) for i in range(15)]  # a..o

# Initial state
initial_on = {
    'a': 'table', 'b': 'a', 'c': 'b',
    'd': 'table', 'e': 'd', 'f': 'e',
    'g': 'table',
    'h': 'table', 'i': 'table', 'j': 'table',
    'k': 'table', 'l': 'table', 'm': 'table',
    'n': 'table',
    # 'o' is held, not on table
}
initial_hand = 'o'  # we start holding block o

# Goal state
goal_on = {
    'o': 'table', 'n': 'o', 'm': 'n', 'l': 'm', 'k': 'l',
    'j': 'table', 'i': 'j', 'h': 'i',
    'a': 'table', 'b': 'table', 'c': 'table',
    'd': 'table', 'e': 'table', 'f': 'table',
    'g': 'table',
}
goal_hand = None  # hand must be empty at the end

def state_key(hand, on_dict):
    """Return a hashable representation of a state."""
    return (hand, frozenset(on_dict.items()))

def clear_blocks(on_dict, hand):
    """Return the set of blocks that have nothing on top of them."""
    supported = {v for v in on_dict.values() if v != 'table'}
    clear = set(blocks) - supported
    # The block we are holding is also considered clear (it has nothing on it)
    if hand is not None:
        clear.add(hand)
    return clear

def is_goal(hand, on_dict):
    return hand == goal_hand and on_dict == goal_on

def successors(hand, on_dict):
    """Generate (action_str, new_hand, new_on_dict) tuples."""
    clear = clear_blocks(on_dict, hand)

    # Pickup actions
    if hand is None:
        for b in blocks:
            if b in on_dict and on_dict[b] == 'table' and b in clear:
                new_on = dict(on_dict)
                del new_on[b]  # block is now held, no longer on anything
                yield (f"(pickup {b})", b, new_on)

    # Putdown actions
    if hand is not None:
        b = hand
        new_on = dict(on_dict)
        new_on[b] = 'table'
        yield (f"(putdown {b})", None, new_on)

    # Unstack actions
    if hand is None:
        for b in blocks:
            if b in on_dict and on_dict[b] != 'table' and b in clear:
                support = on_dict[b]
                new_on = dict(on_dict)
                del new_on[b]  # now held
                yield (f"(unstack {b} {support})", b, new_on)

    # Stack actions
    if hand is not None:
        b = hand
        for target in clear:
            if target == b:
                continue
            # cannot stack onto table (use putdown instead)
            new_on = dict(on_dict)
            new_on[b] = target
            yield (f"(stack {b} {target})", None, new_on)

def bfs():
    start_key = state_key(initial_hand, initial_on)
    queue = deque()
    queue.append((initial_hand, dict(initial_on), []))
    visited = {start_key}
    while queue:
        hand, on_dict, plan = queue.popleft()
        if is_goal(hand, on_dict):
            return plan
        for action_str, new_hand, new_on in successors(hand, on_dict):
            key = state_key(new_hand, new_on)
            if key in visited:
                continue
            visited.add(key)
            queue.append((new_hand, new_on, plan + [action_str]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(act)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from collections import deque

# Blocks are numbered 1..6
N = 6

# Initial locations: 0 = table, else block number it sits on
# block4 on table, block3 on 4; block1 on table; block6 on table, block2 on 6; block5 on table
init_locs = [0, 6, 4, 0, 0, 0]  # index 0->block1, etc.

# Goal locations
goal_locs = [0, 0, 0, 3, 0, 0]

def is_clear(locs, block):
    """block is clear if no other block is on it."""
    return all(l != block for l in locs)

def state_key(arm, locs, stacked):
    """Hashable representation of a state."""
    return (arm, tuple(locs), frozenset(stacked))

def successors(state):
    arm, locs, stacked = state
    res = []
    # Helper to generate actions
    def add(action, new_state):
        res.append((action, new_state))

    # pickup X : arm empty, X on table, X clear
    if arm is None:
        for i, loc in enumerate(locs):
            blk = i + 1
            if loc == 0 and is_clear(locs, blk):
                new_locs = locs[:]
                new_locs[i] = -1  # -1 denotes held
                add(('pickup', blk), (blk, new_locs, stacked))

    # putdown X : arm holds X
    if arm is not None:
        blk = arm
        i = blk - 1
        new_locs = locs[:]
        new_locs[i] = 0
        add(('putdown', blk), (None, new_locs, stacked))

    # unstack X Y : arm empty, X on Y, X clear
    if arm is None:
        for i, loc in enumerate(locs):
            blk = i + 1
            if loc > 0:  # on some block Y
                y = loc
                if is_clear(locs, blk) and blk not in stacked:
                    new_locs = locs[:]
                    new_locs[i] = -1
                    add(('unstack', blk, y), (blk, new_locs, stacked))

    # stack X Y : arm holds X, Y clear
    if arm is not None:
        blk = arm
        for y in range(1, N + 1):
            if y == blk:
                continue
            if is_clear(locs, y):
                new_locs = locs[:]
                new_locs[blk - 1] = y
                new_stacked = set(stacked)
                new_stacked.add(blk)  # X has been stacked
                add(('stack', blk, y), (None, new_locs, new_stacked))

    return res

def is_goal(locs):
    return all(locs[i] == goal_locs[i] for i in range(N))

def bfs():
    start = (None, init_locs, set())
    start_key = state_key(*start)
    queue = deque([start])
    parent = {start_key: None}
    action_taken = {}

    while queue:
        state = queue.popleft()
        arm, locs, stacked = state
        if is_goal(locs):
            # reconstruct plan
            plan = []
            key = state_key(*state)
            while parent[key] is not None:
                plan.append(action_taken[key])
                key = parent[key]
            plan.reverse()
            return plan
        for act, nxt in successors(state):
            key = state_key(*nxt)
            if key not in parent:
                parent[key] = state_key(*state)
                action_taken[key] = act
                queue.append(nxt)
    return None

def format_action(act):
    if act[0] in ('pickup', 'putdown'):
        return f"({act[0]} block{act[1]})"
    else:
        return f"({act[0]} block{act[1]} block{act[2]})"

def main():
    plan = bfs()
    if not plan:
        print("No plan")
        return
    for act in plan:
        print(format_action(act))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from collections import deque

# Blocks are numbered 1..14
N = 14
blocks = list(range(1, N + 1))

# Initial support: 0 = table, else block number it is on
init_support = [0] * (N + 1)  # index 0 unused
# Table blocks
for b in [5, 12, 11, 3, 7, 2, 10, 4, 1]:
    init_support[b] = 0
# Stacks
init_support[6] = 12
init_support[9] = 6
init_support[13] = 11
init_support[14] = 13
init_support[8] = 4

# Goal support
goal_support = [0] * (N + 1)
for b in [13, 10, 11, 4, 8, 12, 6, 9, 1, 2, 3, 5, 7]:
    goal_support[b] = 0
goal_support[14] = 3  # block14 on block3

def clear_blocks(support):
    """Return set of clear blocks given support list."""
    occupied = set(support[1:]) - {0}
    return {b for b in blocks if b not in occupied}

def state_key(holding, support):
    """Hashable representation of a state."""
    return (holding, tuple(support[1:]))

def is_goal(holding, support):
    if holding is not None:
        return False
    return all(support[i] == goal_support[i] for i in blocks)

def successors(holding, support):
    """Generate (action_str, new_holding, new_support) tuples."""
    cur_clear = clear_blocks(support)
    succ = []

    if holding is None:
        # pickup from table
        for b in cur_clear:
            if support[b] == 0:
                new_support = support[:]
                new_support[b] = -1  # -1 denotes held
                succ.append((f"(pickup block{b})", b, new_support))
        # unstack
        for b in cur_clear:
            if support[b] != 0:
                below = support[b]
                new_support = support[:]
                new_support[b] = -1
                succ.append((f"(unstack block{b} block{below})", b, new_support))
    else:
        h = holding
        # putdown
        new_support = support[:]
        new_support[h] = 0
        succ.append((f"(putdown block{h})", None, new_support))
        # stack onto any clear block except itself
        for b in cur_clear:
            if b == h:
                continue
            new_support = support[:]
            new_support[h] = b
            succ.append((f"(stack block{h} block{b})", None, new_support))

    return succ

def bfs():
    start_support = init_support[:]
    start_holding = None
    start_key = state_key(start_holding, start_support)
    queue = deque()
    queue.append((start_holding, start_support, []))
    visited = {start_key}
    while queue:
        holding, support, path = queue.popleft()
        if is_goal(holding, support):
            return path
        for act_str, new_holding, new_support in successors(holding, support):
            # Clean held marker: replace -1 with proper holding flag
            # In support list, held block has value -1; we keep that for consistency
            key = state_key(new_holding, new_support)
            if key in visited:
                continue
            visited.add(key)
            queue.append((new_holding, new_support, path + [act_str]))
    return None

plan = bfs()
if plan is None:
    print("No plan")
else:
    for line in plan:
        print(line)

import collections

# ---------- problem definition ----------
blocks = list(range(1, 10))  # 1..9

# initial state: all on table, arm empty, no timer
init_on = [0] * 10
for b in blocks:
    init_on[b] = 0
init_state = (tuple(init_on), 0, None)  # (on tuple, holding, timer)

# goal mapping: on[block] = block it rests on (0 = table)
goal_on = [0] * 10
goal_on[8] = 0
goal_on[3] = 8
goal_on[6] = 3
goal_on[5] = 6
goal_on[2] = 5
goal_on[1] = 2
goal_on[9] = 1
goal_on[4] = 9
goal_on[7] = 4
goal_state_on = tuple(goal_on)

# ---------- helper functions ----------
def clear_blocks(on, holding):
    """Return a set of blocks that are clear (nothing on top) and not being held."""
    occupied = {on[b] for b in blocks if on[b] != 0}
    clear = {b for b in blocks if b not in occupied}
    if holding:
        clear.discard(holding)
    return clear

def apply_action(state, action):
    """Return the new state after performing action."""
    on, holding, timer = state
    on = list(on)  # mutable copy
    act, i, j = action  # j may be None

    # move block1 -> start timer
    if act in ('pickup', 'unstack') and i == 1:
        timer = 4
    # move block2 while timer active -> clear timer
    if timer is not None and act in ('pickup', 'unstack') and i == 2:
        timer = None

    # decrement timer after the action (if still active)
    if timer is not None:
        timer -= 1
        if timer == 0:
            return None  # constraint violated

    if act == 'pickup':
        holding = i
        # block i leaves the table (its on value stays 0, but it's held)
    elif act == 'unstack':
        holding = i
        on[i] = 0          # temporarily not on anything
    elif act == 'putdown':
        holding = 0
        on[i] = 0          # on the table
    elif act == 'stack':
        holding = 0
        on[i] = j          # i now on j
    else:
        raise ValueError('unknown action')
    return (tuple(on), holding, timer)

def is_goal(state):
    on, holding, timer = state
    return on == goal_state_on and holding == 0 and (timer is None or timer >= 0)

def format_action(action):
    act, i, j = action
    name = f'block{i}'
    if act in ('pickup', 'putdown'):
        return f'({act} {name})'
    else:
        return f'({act} {name} block{j})'

# ---------- BFS search ----------
def bfs():
    start = init_state
    queue = collections.deque()
    queue.append((start, []))
    visited = set()
    visited.add(start)

    while queue:
        state, plan = queue.popleft()
        if is_goal(state):
            return plan

        on, holding, timer = state
        clear = clear_blocks(on, holding)

        # generate actions
        if holding == 0:
            # pickup from table
            for b in clear:
                if on[b] == 0:
                    act = ('pickup', b, None)
                    new_state = apply_action(state, act)
                    if new_state and new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, plan + [act]))
            # unstack
            for b in clear:
                if on[b] != 0:
                    act = ('unstack', b, on[b])
                    new_state = apply_action(state, act)
                    if new_state and new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, plan + [act]))
        else:
            # putdown
            act = ('putdown', holding, None)
            new_state = apply_action(state, act)
            if new_state and new_state not in visited:
                visited.add(new_state)
                queue.append((new_state, plan + [act]))
            # stack onto any clear block
            for b in clear:
                act = ('stack', holding, b)
                new_state = apply_action(state, act)
                if new_state and new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, plan + [act]))
    return None

# ---------- main ----------
plan = bfs()
if plan is None:
    print('No plan')
else:
    for a in plan:
        print(format_action(a))

#!/usr/bin/env python3
import sys
from collections import deque

# Blocks are numbered 1..10, names are "block1", etc.
BLOCKS = tuple(range(1, 11))

# Initial state: all blocks on the table, hand empty.
# State representation:
#   hand: 0 if empty, otherwise block number being held.
#   loc: tuple where loc[i-1] is 0 for table or j for being on block j.
def initial_state():
    return (0, tuple(0 for _ in BLOCKS))

# Goal locations (0 = table)
GOAL_LOC = {
    1: 0,
    2: 9,
    3: 0,
    4: 0,
    5: 0,
    6: 5,
    7: 6,
    8: 4,
    9: 3,
    10: 1,
}
GOAL_TUPLE = tuple(GOAL_LOC[i] for i in BLOCKS)

# Additional ordering constraints
NEXT_AFTER_MOVE = {
    2: 4,   # after moving block2, must move block4 next
    4: 6,   # after moving block4, must move block6 next
}

def is_goal(state):
    _, loc = state
    return loc == GOAL_TUPLE

def clear_blocks(loc):
    """Return a set of blocks that have nothing on top of them."""
    occupied = {b for b in BLOCKS if loc[b-1] != 0}
    return set(BLOCKS) - occupied

def possible_actions(state, must_move):
    hand, loc = state
    clears = clear_blocks(loc)
    actions = []

    if hand == 0:  # hand empty: can pickup or unstack
        # pickup from table
        for b in BLOCKS:
            if b in clears and loc[b-1] == 0:
                if must_move is None or must_move == b:
                    actions.append(('pickup', b, None))
        # unstack from another block
        for b in BLOCKS:
            if b in clears and loc[b-1] != 0:
                below = loc[b-1]
                if must_move is None or must_move == b:
                    actions.append(('unstack', b, below))
    else:  # holding a block
        held = hand
        # putdown on table
        if must_move is None or must_move == held:
            actions.append(('putdown', held, None))
        # stack onto a clear block
        for b in BLOCKS:
            if b in clears and b != held:
                if must_move is None or must_move == held:
                    actions.append(('stack', held, b))
    return actions

def apply_action(state, action):
    hand, loc = state
    act, x, y = action
    loc = list(loc)
    if act == 'pickup':
        # x is on table, hand empty
        new_hand = x
        # location unchanged (still on table) until stacked
    elif act == 'unstack':
        # x is on y
        new_hand = x
        loc[x-1] = 0  # now on table (temporarily)
    elif act == 'putdown':
        # put held block x onto table
        new_hand = 0
        loc[x-1] = 0
    elif act == 'stack':
        # stack held block x onto y
        new_hand = 0
        loc[x-1] = y
    else:
        raise ValueError('unknown action')
    return (new_hand, tuple(loc))

def format_action(action):
    act, x, y = action
    name = f'block{x}'
    if act in ('pickup', 'putdown'):
        return f'({act} {name})'
    elif act == 'unstack':
        return f'({act} {name} block{y})'
    elif act == 'stack':
        return f'({act} {name} block{y})'
    else:
        return ''

def solve():
    start = initial_state()
    # BFS to guarantee finding a short plan
    frontier = deque()
    frontier.append((start, [], None))  # state, plan, must_move_next
    visited = set()
    visited.add(start + (None,))

    while frontier:
        state, plan, must_move = frontier.popleft()
        if is_goal(state):
            for act in plan:
                print(format_action(act))
            return

        for act in possible_actions(state, must_move):
            new_state = apply_action(state, act)
            # Determine next must_move constraint
            # Constraint triggers after a block is placed (i.e., after stack or putdown)
            next_must = None
            if act[0] in ('stack', 'putdown'):
                moved_block = act[1]
                if moved_block in NEXT_AFTER_MOVE:
                    next_must = NEXT_AFTER_MOVE[moved_block]
            # When hand becomes empty after a placement, the next action must move that block
            key = new_state + (next_must,)
            if key not in visited:
                visited.add(key)
                frontier.append((new_state, plan + [act], next_must))

    print('No plan')

if __name__ == '__main__':
    solve()

