    actions = []
    # generate pickup actions
    if state_arm is None:
        for b in range(1, N + 1):
            if state_on[b] == 0 and is_clear(state_on, b):
                actions.append(('pickup', b, None))
    # generate unstack actions
    if state_arm is None:
        for b in range(1, N + 1):
            y = state_on[b]
            if y != 0 and is_clear(state_on, b):
                actions.append(('unstack', b, y))
    # generate putdown actions
    if state_arm is not None:
        actions.append(('putdown', state_arm, None))
    # generate stack actions
    if state_arm is not None:
        for y in range(1, N + 1):
            if is_clear(state_on, y):
                actions.append(('stack', state_arm, y))
    return actions

def apply_action(state_arm, state_on, action):
    act, x, y = action
    new_on = list(state_on)
    new_arm = state_arm
    if act == 'pickup':
        new_arm = x
        new_on[x] = None  # temporarily not on anything
    elif act == 'unstack':
        new_arm = x
        new_on[x] = None
    elif act == 'putdown':
        new_on[x] = 0
        new_arm = None
    elif act == 'stack':
        new_on[x] = y
        new_arm = None
    # replace None with 0 for consistency (means not placed yet)
    for i in range(1, N + 1):
        if new_on[i] is None:
            new_on[i] = 0
    return new_arm, tuple(new_on)

def heuristic(state_arm, state_on):
    # number of blocks not on correct support
    mis = sum(1 for b in range(1, N + 1) if state_on[b] != goal_on[b])
    # plus 1 if arm holds a block that shouldn't be held
    if state_arm is not None:
        mis += 1
    return mis

def state_key(state_arm, state_on):
    return (state_arm, state_on)

def a_star():
    start = (init_arm, tuple(init_on))
    frontier = [(heuristic(*start), 0, start, [])]  # (f, g, state, path)
    visited = set()
    while frontier:
        f, g, (arm, on), path = heapq.heappop(frontier)
        if (arm, on) in visited:
            continue
        visited.add((arm, on))
        # goal test
        if arm is None and all(on[b] == goal_on[b] for b in range(1, N + 1)):
            return path
        for act in applicable_actions(arm, on):
            new_arm, new_on = apply_action(arm, on, act)
            if (new_arm, new_on) in visited:
                continue
            new_path = path + [act]
            h = heuristic(new_arm, new_on)
            heapq.heappush(frontier, (g + 1 + h, g + 1, (new_arm, new_on), new_path))
    return None

def format_action(act):
    name, x, y = act
    if name in ('pickup', 'putdown'):
        return f'({name} block{x})'
    elif name in ('unstack', 'stack'):
        return f'({name} block{x} block{y})'

def main():
    plan = a_star()
    if plan is None:
        print("No plan")
    else:
        for a in plan:
            print(format_action(a))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys
from collections import deque

# ---------- Problem definition ----------
N = 13  # number of blocks, ids 1..13

# initial configuration: on[block] = supporting block (0 = table)
init_on = [0] * (N + 1)
# helper to set a stack from bottom to top
def set_stack(bottom, *stack):
    prev = bottom
    for b in stack:
        init_on[b] = prev
        prev = b

# given description
# 2 on table
init_on[2] = 0
# 10 table, 13 on 10, 9 on 13, 1 on 9
set_stack(10, 13, 9, 1)
# 4 table, 7 on 4
set_stack(4, 7)
# 11 table
init_on[11] = 0
# 5 table, 12 on 5
set_stack(5, 12)
# 8 table, 6 on 8, 3 on 6
set_stack(8, 6, 3)

# goal configuration
goal_on = [0] * (N + 1)
# 1 table, 6 on 1, 3 on 6, 9 on 3, 5 on 9
set_stack(1, 6, 3, 9, 5)
# 13 table, 7 on 13
set_stack(13, 7)
# 11 table
goal_on[11] = 0
# 12 table, 10 on 12, 8 on 10, 2 on 8, 4 on 2
set_stack(12, 10, 8, 2, 4)

# ---------- State utilities ----------
def clear_blocks(on):
    """Return a set of blocks that are clear given the 'on' list."""
    occupied = [False] * (N + 1)
    for b in range(1, N + 1):
        sup = on[b]
        if sup != 0:
            occupied[sup] = True
    return {b for b in range(1, N + 1) if not occupied[b]}

def state_hash(holding, on):
    """Hashable representation of a state."""
    return (holding, tuple(on[1:]))

def is_goal(holding, on):
    return holding == 0 and on[1:] == goal_on[1:]

def heuristic(holding, on):
    """Number of blocks whose support differs from goal (excluding held block)."""
    h = 0
    for b in range(1, N + 1):
        if b == holding:
            continue
        if on[b] != goal_on[b]:
            h += 1
    # if we are holding a block that should be on something, we will need at least one move
    if holding != 0 and goal_on[holding] != 0:
        h += 1
    return h

# ---------- Action generation ----------
def generate_actions(holding, on):
    clear = clear_blocks(on)
    actions = []
    if holding == 0:
        # can pickup from table
        for b in clear:
            if on[b] == 0:
                actions.append(('pickup', b, None))
        # can unstack
        for b in clear:
            sup = on[b]
            if sup != 0:
                actions.append(('unstack', b, sup))
    else:
        # putdown
        actions.append(('putdown', holding, None))
        # stack onto any clear block except itself
        for y in clear:
            if y != holding:
                actions.append(('stack', holding, y))
    return actions

def apply_action(state, action):
    holding, on = state
    act, x, y = action
    new_on = on[:]  # copy list
    new_holding = holding
    if act == 'pickup':
        new_holding = x
        new_on[x] = 0  # removed from table
    elif act == 'unstack':
        new_holding = x
        new_on[x] = 0  # lifted, no support now
    elif act == 'putdown':
        new_holding = 0
        new_on[x] = 0  # placed on table
    elif act == 'stack':
        new_holding = 0
        new_on[x] = y
    return (new_holding, new_on)

def action_to_str(action):
    act, x, y = action
    name = f'block{x}'
    if act in ('pickup', 'putdown'):
        return f'({act} {name})'
    else:
        other = f'block{y}'
        return f'({act} {name} {other})'

# ---------- IDA* search ----------
sys.setrecursionlimit(10000)

start_state = (0, init_on[:])  # holding, on list copy

threshold = heuristic(*start_state)
found_plan = None

def dfs(state, g, bound, path, visited):
    global found_plan
    f = g + heuristic(*state)
    if f > bound:
        return f
    if is_goal(*state):
        found_plan = path[:]
        return -1  # success signal
    min_over = float('inf')
    for act in generate_actions(*state):
        nxt = apply_action(state, act)
        hsh = state_hash(*nxt)
        if hsh in visited:
            continue
        visited.add(hsh)
        path.append(act)
        t = dfs(nxt, g + 1, bound, path, visited)
        if t == -1:
            return -1
        if t < min_over:
            min_over = t
        path.pop()
        visited.remove(hsh)
    return min_over

while True:
    visited = {state_hash(*start_state)}
    t = dfs(start_state, 0, threshold, [], visited)
    if t == -1:
        break
    if t == float('inf'):
        break
    threshold = t

# ---------- Output ----------
if found_plan is None:
    print("No plan")
else:
    out = "\n".join(action_to_str(a) for a in found_plan)
    sys.stdout.write(out)

#!/usr/bin/env python3
import collections

# Blocks
blocks = [f"block{i}" for i in range(1, 9)]

# Initial configuration
# on[block] = what the block is directly on ('table' or another block)
initial_on = {
    "block1": "table",
    "block2": "table",
    "block3": "block5",
    "block4": "table",
    "block5": "table",
    "block6": "block3",
    "block7": "table",
    "block8": "block2",
}
initial_held = None  # arm empty

# Goal conditions (excluding the extra requirement of holding block3)
goal_on = {
    "block8": "table",
    "block7": "block8",
    "block2": "block7",
    "block4": "block2",
    "block5": "block4",
    "block6": "table",
    "block1": "block6",
}
goal_held = "block3"  # must be holding block3 at the end


def state_key(on_dict, held):
    """Create a hashable representation of a state."""
    # Order the on values according to blocks list
    on_tuple = tuple(on_dict[b] for b in blocks)
    return (held, on_tuple)


def clear_blocks(on_dict, held):
    """Return the set of blocks that are clear (nothing on top)."""
    occupied = {v for v in on_dict.values() if v != "table"}
    # a block is clear if no other block is on it and it is not being held
    return {b for b in blocks if b not in occupied and b != held}


def is_goal(on_dict, held):
    """Check if a state satisfies the goal."""
    if held != goal_held:
        return False
    for b, loc in goal_on.items():
        if on_dict.get(b) != loc:
            return False
    return True


def bfs():
    start_key = state_key(initial_on, initial_held)
    queue = collections.deque()
    queue.append((initial_on, initial_held, []))
    visited = {start_key}

    while queue:
        on_dict, held, plan = queue.popleft()

        if is_goal(on_dict, held):
            return plan

        clear = clear_blocks(on_dict, held)

        # Generate possible actions
        if held is None:
            # pickup from table
            for b in clear:
                if on_dict[b] == "table":
                    new_on = on_dict.copy()
                    new_on[b] = None  # not on anything while held
                    new_plan = plan + [f"(pickup {b})"]
                    key = state_key(new_on, b)
                    if key not in visited:
                        visited.add(key)
                        queue.append((new_on, b, new_plan))
            # unstack
            for b in clear:
                loc = on_dict[b]
                if loc not in (None, "table"):
                    new_on = on_dict.copy()
                    new_on[b] = None
                    new_plan = plan + [f"(unstack {b} {loc})"]
                    key = state_key(new_on, b)
                    if key not in visited:
                        visited.add(key)
                        queue.append((new_on, b, new_plan))
        else:
            # putdown
            new_on = on_dict.copy()
            new_on[held] = "table"
            new_plan = plan + [f"(putdown {held})"]
            key = state_key(new_on, None)
            if key not in visited:
                visited.add(key)
                queue.append((new_on, None, new_plan))

            # stack onto any clear block (except itself)
            for b in clear:
                new_on = on_dict.copy()
                new_on[held] = b
                new_plan = plan + [f"(stack {held} {b})"]
                key = state_key(new_on, None)
                if key not in visited:
                    visited.add(key)
                    queue.append((new_on, None, new_plan))
    return None


def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            print(action)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import collections

# Blocks
blocks = [chr(ord('A') + i) for i in range(13)]  # A..M
goal_order = blocks[:]  # A to M

# Initial configuration (with G held)
on = {
    'A': 'table', 'B': 'A', 'C': 'B',
    'D': 'table', 'E': 'D', 'F': 'E', 'G': None,   # G is held
    'H': 'table', 'I': 'H', 'J': 'I', 'K': 'J', 'L': 'K',
    'M': 'table'
}
holding = 'G'  # start holding G

def is_clear(state_on, blk):
    """A block is clear if no other block is on it."""
    return all(state_on.get(b) != blk for b in blocks)

def state_key(state_on, holding):
    """Immutable representation for visited set."""
    # sort items to make deterministic
    items = tuple(sorted((b, state_on[b]) for b in blocks))
    return (items, holding)

def goal_test(state_on, holding):
    if holding is not None:
        return False
    for i, blk in enumerate(goal_order):
        expected = 'table' if i == 0 else goal_order[i - 1]
        if state_on[blk] != expected:
            return False
    return True

def successors(state_on, holding):
    succ = []
    # precompute clear set
    clear = {b for b in blocks if is_clear(state_on, b)}
    if holding is None:
        # pickup
        for b in blocks:
            if state_on[b] == 'table' and b in clear:
                new_on = state_on.copy()
                new_on[b] = None
                succ.append(((new_on, b), ('pickup', b)))
        # unstack
        for b in blocks:
            below = state_on[b]
            if below not in (None, 'table') and b in clear:
                new_on = state_on.copy()
                new_on[b] = None
                succ.append(((new_on, b), ('unstack', b, below)))
    else:
        h = holding
        # putdown
        new_on = state_on.copy()
        new_on[h] = 'table'
        succ.append(((new_on, None), ('putdown', h)))
        # stack onto any clear block (except itself)
        for y in clear:
            if y == h:
                continue
            new_on = state_on.copy()
            new_on[h] = y
            succ.append(((new_on, None), ('stack', h, y)))
    return succ

def bfs(initial_on, initial_holding):
    start_key = state_key(initial_on, initial_holding)
    queue = collections.deque()
    queue.append((initial_on, initial_holding, []))
    visited = {start_key}
    while queue:
        cur_on, cur_holding, path = queue.popleft()
        if goal_test(cur_on, cur_holding):
            return path
        for (new_on, new_holding), action in successors(cur_on, cur_holding):
            k = state_key(new_on, new_holding)
            if k in visited:
                continue
            visited.add(k)
            queue.append((new_on, new_holding, path + [action]))
    return None

def format_action(act):
    name = act[0]
    if name in ('pickup', 'putdown'):
        return f"({name} block{act[1]})"
    else:
        return f"({name} block{act[1]} block{act[2]})"

def main():
    plan = bfs(on, holding)
    if plan is None:
        print("No plan")
    else:
        for a in plan:
            print(format_action(a))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# Blocksworld planner for the given problem

blocks = [f"block{i}" for i in range(1, 12)]

# initial state: single tower 1(bottom) .. 11(top)
on = {}
for i in range(1, 12):
    if i == 1:
        on[f"block{i}"] = "table"
    else:
        on[f"block{i}"] = f"block{i-1}"

# goal configuration
goal_on = {
    "block2": "table",
    "block5": "block2",
    "block8": "table",
    "block11": "table",
    "block9": "block11",
    "block4": "table",
    "block1": "table",
    "block10": "block1",
    "block3": "table",
    "block6": "table",
    "block7": "block6",
}

def is_clear(b):
    """A block is clear if no other block stands on it."""
    return b not in on.values()

def state_is_goal():
    for b in blocks:
        if on.get(b) != goal_on.get(b):
            return False
    return True

actions = []
holding = None  # None or block name

max_steps = 1000
steps = 0

while not state_is_goal() and steps < max_steps:
    # find a clear block that is not in its goal position
    candidate = None
    for b in blocks:
        if is_clear(b) and on.get(b) != goal_on.get(b):
            candidate = b
            break
    if candidate is None:
        break  # no movable block found

    # pick up / unstack the candidate
    if holding is not None:
        # should never happen
        break
    current_support = on[candidate]
    if current_support == "table":
        actions.append(f"(pickup {candidate})")
        holding = candidate
        on[candidate] = None
    else:
        actions.append(f"(unstack {candidate} {current_support})")
        holding = candidate
        on[candidate] = None

    # decide where to place it
    goal_support = goal_on[candidate]
    if goal_support == "table":
        actions.append(f"(putdown {candidate})")
        holding = None
        on[candidate] = "table"
    else:
        if is_clear(goal_support):
            actions.append(f"(stack {candidate} {goal_support})")
            holding = None
            on[candidate] = goal_support
        else:
            # temporary place on table
            actions.append(f"(putdown {candidate})")
            holding = None
            on[candidate] = "table"

    steps += 1

if state_is_goal():
    for a in actions:
        print(a)
else:
    print("No plan")

import collections

# Define blocks
blocks = list(range(1, 15))

# Helper to convert block number to name
def name(b):
