    7: 'table', 5: 7, 8: 5, 9: 8, 3: 9, 12: 3, 14: 12,
    10: 'table', 6: 10, 13: 6, 11: 13,
    4: 'table', 2: 4, 1: 2
}
for b in blocks:
    goal_on.setdefault(b, None)

def is_clear(on_map, block):
    return block not in on_map.values()

def state_key(on_map, holding):
    # tuple of supports ordered by block number, plus holding
    supports = tuple(on_map[b] if on_map[b] != 'table' else 'table' for b in blocks)
    return (holding, supports)

def successors(on_map, holding):
    succ = []
    # compute clear blocks
    clear = {b for b in blocks if is_clear(on_map, b)}
    if holding is None:
        # pickup from table
        for b in clear:
            if on_map[b] == 'table':
                new_on = on_map.copy()
                new_on[b] = None  # being held
                succ.append(((new_on, b), f"(pickup {name(b)})"))
        # unstack
        for b in clear:
            below = on_map[b]
            if below not in (None, 'table'):
                new_on = on_map.copy()
                new_on[b] = None
                succ.append(((new_on, b), f"(unstack {name(b)} {name(below)})"))
    else:
        # putdown
        new_on = on_map.copy()
        new_on[holding] = 'table'
        succ.append(((new_on, None), f"(putdown {name(holding)})"))
        # stack onto any clear block (cannot stack onto itself)
        for b in clear:
            if b == holding:
                continue
            new_on = on_map.copy()
            new_on[holding] = b
            succ.append(((new_on, None), f"(stack {name(holding)} {name(b)})"))
    return succ

def is_goal(on_map, holding):
    if holding is not None:
        return False
    for b in blocks:
        if on_map[b] != goal_on[b]:
            return False
    return True

def bfs():
    start_on = init_on.copy()
    start_holding = None
    start_key = state_key(start_on, start_holding)
    queue = collections.deque()
    queue.append((start_on, start_holding))
    visited = {start_key}
    parent = {start_key: (None, None)}  # key -> (prev_key, action)
    while queue:
        on_map, holding = queue.popleft()
        if is_goal(on_map, holding):
            # reconstruct path
            actions = []
            cur_key = state_key(on_map, holding)
            while parent[cur_key][0] is not None:
                prev_key, act = parent[cur_key]
                actions.append(act)
                cur_key = prev_key
            actions.reverse()
            return actions
        for (new_on, new_holding), act in successors(on_map, holding):
            key = state_key(new_on, new_holding)
            if key not in visited:
                visited.add(key)
                parent[key] = (state_key(on_map, holding), act)
                queue.append((new_on, new_holding))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for a in plan:
            print(a)

if __name__ == "__main__":
