#!/usr/bin/env python3
import collections

# Blocks are numbered 1..9
BLOCKS = tuple(range(1, 10))
TABLE = 0

# Initial configuration: mapping block -> support (0 = table)
initial_on = {
    7: TABLE,
    2: 7,
    9: 2,
    1: 9,
    4: 1,
    6: 4,
    5: 6,
    3: 5,
    8: 3,
}

# Goal configuration
goal_on = {
    8: TABLE,
    9: 8,
    2: TABLE,
    4: 2,
    3: 4,
    7: 3,
    6: TABLE,
    1: TABLE,
    5: 1,
}

def clear_blocks(on_map):
    """Return set of blocks that have nothing on top of them."""
    occupied = {support for support in on_map.values() if support != TABLE}
    return set(BLOCKS) - occupied

def state_key(holding, on_map):
    """Immutable representation for hashing."""
    items = tuple(sorted(on_map.items()))
    return (holding, items)

def is_goal(holding, on_map):
    return holding is None and all(on_map.get(b, None) == goal_on[b] for b in BLOCKS)

def successors(state):
    holding, on_map = state
    clear = clear_blocks(on_map)
    succ = []
    if holding is None:
        # pickup from table
        for b in clear:
            if on_map[b] == TABLE:
                new_on = dict(on_map)
                del new_on[b]  # block removed from table
                succ.append(((b, new_on), ('pickup', b)))
        # unstack
        for b in clear:
            support = on_map[b]
            if support != TABLE:
                new_on = dict(on_map)
                del new_on[b]  # lifted off its support
                succ.append(((b, new_on), ('unstack', b, support)))
    else:
        # putdown on table
        new_on = dict(on_map)
        new_on[holding] = TABLE
        succ.append(((None, new_on), ('putdown', holding)))
        # stack onto a clear block (avoid forbidden stack)
        for b in clear:
            if b == holding:
                continue
            # additional constraint: never stack block1 on block3
            if holding == 1 and b == 3:
                continue
            new_on2 = dict(on_map)
            new_on2[holding] = b
            succ.append(((None, new_on2), ('stack', holding, b)))
    return succ

def bfs():
    start_state = (None, dict(initial_on))
    start_key = state_key(*start_state)
    frontier = collections.deque([start_state])
    visited = {start_key: None}
    action_from = {}
    while frontier:
        state = frontier.popleft()
        holding, on_map = state
        if is_goal(holding, on_map):
            # reconstruct plan
            plan = []
            cur_key = state_key(holding, on_map)
            while visited[cur_key] is not None:
                prev_key, act = action_from[cur_key]
                plan.append(act)
                cur_key = prev_key
            plan.reverse()
            return plan
        for nxt_state, act in successors(state):
            nxt_key = state_key(*nxt_state)
            if nxt_key in visited:
                continue
            visited[nxt_key] = state_key(holding, on_map)
            action_from[nxt_key] = (state_key(holding, on_map), act)
            frontier.append(nxt_state)
    return None

def fmt_action(act):
    if act[0] in ('pickup', 'putdown'):
        return f"({act[0]} block{act[1]})"
    else:
        return f"({act[0]} block{act[1]} block{act[2]})"

def main():
