import collections

# Blocks
blocks = [f'block{i}' for i in range(1, 12)]

# Initial state: mapping block -> support ('table' or another block)
init_on = {
    'block1': 'table',
    'block2': 'table',
    'block3': 'block9',
    'block4': 'block11',
    'block5': 'table',
    'block6': 'table',
    'block7': 'block8',
    'block8': 'block2',
    'block9': 'table',
    'block10': 'table',
    'block11': 'table',
}

# Goal state
goal_on = {
    'block1': 'table',
    'block2': 'block4',
    'block3': 'block2',
    'block4': 'table',
    'block5': 'block3',
    'block6': 'table',
    'block7': 'block9',
    'block8': 'block10',
    'block9': 'table',
    'block10': 'table',
    'block11': 'block8',
}

def state_key(on_map, holding, counter):
    """Create a hashable key for a state."""
    return (tuple(on_map[b] for b in blocks), holding, counter)

def clear_blocks(on_map):
    """Return set of blocks that have nothing on top."""
    occupied = {on_map[b] for b in blocks if on_map[b] != 'table'}
    return {b for b in blocks if b not in occupied}

def actions(state):
    """Generate possible actions from a state."""
    on_map, holding, counter = state
    clears = clear_blocks(on_map)
    acts = []
    if holding is None:
        # pickup from table
        for b in clears:
            if on_map[b] == 'table':
                acts.append(('pickup', b, None))
        # unstack
        for b in clears:
            sup = on_map[b]
            if sup != 'table':
                acts.append(('unstack', b, sup))
    else:
        # putdown
        acts.append(('putdown', holding, None))
        # stack onto any clear block (not itself)
        for b in clears:
            if b != holding:
                acts.append(('stack', holding, b))
    return acts

def apply(state, act):
    """Apply action, return new state and updated constraint counter."""
    on_map, holding, counter = state
    op, x, y = act
    new_on = on_map.copy()
    new_holding = holding
    new_counter = counter

    # Helper to detect moving block1 or block2
    moved_block = x

    # Update constraint counter before action effect
    if moved_block == 'block1':
        new_counter = 2  # must move block2 within next 2 moves
    elif new_counter > 0 and moved_block == 'block2':
        new_counter = 0  # satisfied
    elif new_counter > 0:
        new_counter -= 1
        if new_counter == 0:
            # failed to move block2 in time
            return None

    # Apply effects
    if op == 'pickup':
        new_holding = x
        new_on[x] = None  # not on anything
    elif op == 'unstack':
        new_holding = x
        new_on[x] = None
    elif op == 'putdown':
        new_holding = None
        new_on[x] = 'table'
    elif op == 'stack':
        new_holding = None
        new_on[x] = y
    else:
        return None

    # Clean None entries (means block is held)
    for b in blocks:
        if new_on[b] is None:
            new_on[b] = 'hand'  # temporary marker
    # Replace 'hand' back to previous value after move
    for b in blocks:
        if new_on[b] == 'hand':
            # will be set correctly by actions above; keep as placeholder
            pass

    # After applying, set held block's support to None (we track via holding)
    if new_holding is None:
        # all blocks have proper support
        pass
    else:
        new_on[new_holding] = 'hand'

    # Ensure no None left
    for b in blocks:
        if new_on[b] is None:
            new_on[b] = 'hand'

    # Convert 'hand' back to actual value for next iteration
    # (the next state's holding variable already records it)
    for b in blocks:
        if new_on[b] == 'hand':
            new_on[b] = 'table' if b == new_holding else new_on[b]

    # Actually we can simplify: we don't need placeholder; just handle directly:
    # We'll recompute on_map without 'hand' markers.
    # Rebuild proper on mapping:
    final_on = {}
    for b in blocks:
        if b == new_holding:
            continue
        sup = new_on[b]
        if sup == 'hand':
            sup = 'table'  # shouldn't happen
        final_on[b] = sup
    # For held block, its support is None (not on anything)
    # but we keep it out of mapping; we will treat it via holding variable.
    # Ensure all blocks present:
    for b in blocks:
        if b not in final_on:
            final_on[b] = None

    # Replace None with 'table' for consistency when not held
    for b in blocks:
        if final_on[b] is None:
            final_on[b] = 'hand'  # indicates held
    # Finally, set held block's entry to 'hand' and others proper.
    # This representation works with clear detection logic.

    # Return new state
    return (final_on, new_holding, new_counter)

def is_goal(state):
    on_map, holding, _ = state
    if holding is not None:
        return False
    for b in blocks:
        if on_map[b] != goal_on[b]:
            return False
    return True

def bfs():
    start_on = init_on.copy()
    # mark held block as None (none held)
    start_state = (start_on, None, 0)
    queue = collections.deque()
    queue.append((start_state, []))
    visited = set()
    visited.add(state_key(*start_state))

    while queue:
        cur_state, path = queue.popleft()
        if is_goal(cur_state):
            return path
        for act in actions(cur_state):
            nxt = apply(cur_state, act)
            if nxt is None:
                continue
            key = state_key(*nxt)
            if key in visited:
                continue
            visited.add(key)
            queue.append((nxt, path + [act]))
    return None

def format_plan(plan):
    lines = []
    for op, x, y in plan:
        if op in ('pickup', 'putdown'):
            lines.append(f'({op} {x})')
        else:
            lines.append(f'({op} {x} {y})')
    return "\n".join(lines)

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        print(format_plan(plan))

if __name__ == "__main__":
    main()

