        on['block3'] == 'table' and
        on['block4'] == 'block3' and
        on['block6'] == 'table'
    )

# Helper to compute clear blocks from 'on' mapping
def compute_clear(on):
    occupied = {v for v in on.values() if v != 'table'}
    return {b for b in blocks if b not in occupied}

# Generate possible actions from a state
def successors(state):
    on, holding = state
    clear = compute_clear(on)
    succ = []

    # pickup actions
    if holding is None:
        for b in blocks:
            if on[b] == 'table' and b in clear:
                new_on = on.copy()
                new_on[b] = None  # being held
                action = ('pickup', b)
                succ.append(((new_on, b), action))

    # putdown actions
    if holding is not None:
        b = holding
        new_on = on.copy()
        new_on[b] = 'table'
        action = ('putdown', b)
        succ.append(((new_on, None), action))

    # stack actions
    if holding is not None:
        b = holding
        for y in blocks:
            if y != b and y in clear:
                new_on = on.copy()
                new_on[b] = y
                action = ('stack', b, y)
                succ.append(((new_on, None), action))

    # unstack actions
    if holding is None:
        for b in blocks:
            if b in clear:
                y = on[b]
                if y != 'table' and y is not None:
                    new_on = on.copy()
                    new_on[b] = None  # now held
                    action = ('unstack', b, y)
                    succ.append(((new_on, b), action))

    return succ

# Encode state as a hashable object for visited set
def encode(state):
    on, holding = state
    # sort items to ensure deterministic ordering
    items = tuple(sorted((b, on[b]) for b in blocks))
    return (holding, items)

# BFS search
def bfs():
    start_state = (initial_on, initial_holding)
    frontier = collections.deque()
    frontier.append((start_state, []))
    visited = set()
    visited.add(encode(start_state))

    while frontier:
        (state, plan) = frontier.popleft()
        if is_goal(state):
            return plan
        for next_state, action in successors(state):
            key = encode(next_state)
            if key in visited:
                continue
            visited.add(key)
            frontier.append((next_state, plan + [action]))
    return None

