    if act[0] == 'putdown':
        return f"(putdown {act[1]})"
    if act[0] == 'stack':
        return f"(stack {act[1]} {act[2]})"
    if act[0] == 'unstack':
        return f"(unstack {act[1]} {act[2]})"
    return ""

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(format_action(act))

if __name__ == "__main__":
