from collections import deque

# Blocks
blocks = ["block1", "block2", "block3", "block4"]

# Initial state: all on table, arm free
init_on = {b: "table" for b in blocks}
init_holding = None
init_state = (frozenset(init_on.items()), init_holding)

# Goal test
def is_goal(state):
    on_items, holding = state
    on = dict(on_items)
    return (
        on["block1"] == "table"
        and on["block4"] == "block1"
        and on["block3"] == "table"
        and on["block2"] == "block3"
        and holding is None
    )

# Helper to compute clear blocks
def compute_clear(on, holding):
    occupied = {v for v in on.values() if v != "table"}
    clear = {b for b in blocks if b not in occupied}
    if holding:
        clear.discard(holding)
    return clear

# Generate possible actions from a state, respecting extra constraints
def successors(state, prev_primary):
    on_items, holding = state
    on = dict(on_items)
    clear = compute_clear(on, holding)

    actions = []

    # pickup X
    for x in blocks:
        if holding is None and on[x] == "table" and x in clear:
            actions.append(("pickup", x, None))

    # unstack X Y
    for x in blocks:
        y = on[x]
        if holding is None and y != "table" and x in clear:
            actions.append(("unstack", x, y))

    # putdown X
    if holding is not None:
        actions.append(("putdown", holding, None))

    # stack X Y
    if holding is not None:
        for y in blocks:
            if y in clear and y != holding:
                actions.append(("stack", holding, y))

    # Apply extra ordering constraints
    filtered = []
    for act in actions:
        primary = act[1]  # the block being moved
        if prev_primary == "block1" and primary != "block2":
            continue
        if prev_primary == "block2" and primary != "block3":
            continue
        filtered.append(act)
    return filtered

# Apply an action to a state, returning the new state
def apply(state, action):
    on_items, holding = state
    on = dict(on_items)
    act, x, y = action

    if act == "pickup":
        holding = x
    elif act == "unstack":
        holding = x
        on[x] = "table"
    elif act == "putdown":
        on[x] = "table"
        holding = None
    elif act == "stack":
        on[x] = y
        holding = None
    return (frozenset(on.items()), holding)

# BFS search
def bfs():
    queue = deque()
    queue.append((init_state, None, []))  # state, previous primary, plan
    visited = set()
    visited.add((init_state, None))

    while queue:
        state, prev_primary, plan = queue.popleft()
        if is_goal(state):
            return plan
        for act in successors(state, prev_primary):
            new_state = apply(state, act)
            primary = act[1]
            key = (new_state, primary)
            if key in visited:
                continue
            visited.add(key)
            queue.append((new_state, primary, plan + [act]))
    return None

plan = bfs()

if plan is None:
