from collections import deque

# Blocks are numbered 1..9, names are "block1" etc.
blocks = list(range(1, 10))
name = lambda i: f"block{i}"

# Initial state: all on table (0), arm empty (holding = 0)
init_positions = tuple(0 for _ in blocks)   # index i corresponds to block i+1
init_holding = 0
init_state = (init_holding, init_positions)

# Goal configuration (bottom to top): 8,3,6,5,2,1,9,4,7
goal_order = [8, 3, 6, 5, 2, 1, 9, 4, 7]
goal_positions = [0] * 9
for i, blk in enumerate(goal_order):
    if i == 0:               # bottom block on table
        goal_positions[blk - 1] = 0
    else:
        below = goal_order[i - 1]
        goal_positions[blk - 1] = below
goal_state = (0, tuple(goal_positions))   # arm must be empty at goal

def is_clear(positions, b):
    """Return True if no block is on b."""
    return all(pos != b for pos in positions)

def successors(state):
    """Generate (action_str, new_state) pairs."""
    holding, positions = state
    for b in blocks:
        idx = b - 1
        pos = positions[idx]

        # pickup
        if holding == 0 and pos == 0 and is_clear(positions, b):
            new_pos = list(positions)
            new_pos[idx] = -1          # -1 denotes being held (no support)
            yield (f"(pickup {name(b)})", (b, tuple(new_pos)))

        # unstack
        if holding == 0 and pos != 0 and is_clear(positions, b):
            new_pos = list(positions)
            new_pos[idx] = -1
            yield (f"(unstack {name(b)} {name(pos)})", (b, tuple(new_pos)))

        # putdown
        if holding == b and pos == -1:
            new_pos = list(positions)
            new_pos[idx] = 0
            yield (f"(putdown {name(b)})", (0, tuple(new_pos)))

        # stack
        if holding == b and pos == -1:
            for y in blocks:
                if y == b:
                    continue
                if is_clear(positions, y):
                    new_pos = list(positions)
                    new_pos[idx] = y
                    yield (f"(stack {name(b)} {name(y)})", (0, tuple(new_pos)))

def bfs():
    """Breadth‑first search for a plan."""
    queue = deque()
    queue.append((init_state, []))
    visited = {init_state}
    while queue:
        state, plan = queue.popleft()
        if state == goal_state:
            return plan
        for act, ns in successors(state):
            if ns not in visited:
                visited.add(ns)
                queue.append((ns, plan + [act]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(act)

if __name__ == "__main__":
    main()

