        x = holding
        if on_dict[x] == 'hand':
            new_on = on_dict.copy()
            new_on[x] = 'table'
            action = f"(putdown {x})"
            succ.append((None, new_on, action))
    # ACTION: unstack X Y
    if holding is None:
        for x in blocks:
            y = on_dict[x]
            if y != 'table' and y != 'hand' and x in clear_blocks:
                # x is clear and on y
                new_on = on_dict.copy()
                new_on[x] = 'hand'
                action = f"(unstack {x} {y})"
                succ.append((x, new_on, action))
    # ACTION: stack X Y
    if holding is not None:
        x = holding
        for y in blocks:
            if y != x and y in clear_blocks and on_dict[y] != 'hand':
                # y is clear and not being held
                new_on = on_dict.copy()
