                    new_on[y] = new_on[y]  # unchanged; y becomes clear automatically
                    act = f"(unstack block{x} block{y})"
                    succ.append((new_hand, new_on, act))

    # stack X Y
    if hand is not None:
        x = hand
        for y in blocks:
            if y in clear and y != x:
                new_hand = None
                new_on = on.copy()
                new_on[x] = y
                act = f"(stack block{x} block{y})"
                succ.append((new_hand, new_on, act))

    return succ

def bfs():
    start_key = state_key(initial_hand, initial_on)
    queue = deque()
    queue.append((initial_hand, initial_on, []))
    visited = {start_key}
    while queue:
        hand, on, plan = queue.popleft()
        if is_goal(hand, on):
            return plan
        for nh, no, act in successors(hand, on):
            key = state_key(nh, no)
            if key in visited:
                continue
            visited.add(key)
            queue.append((nh, no, plan + [act]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(act)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from collections import deque

# Blocks
BLOCKS = ("red", "blue", "green", "yellow")

# Initial state
# hand holds the block name or None
initial_hand = "blue"
# mapping block -> support ('table' or another block)
initial_on = {
    "red": "table",
    "green": "table",
    "yellow": "green",
    # blue is being held, so not in the mapping
}

# Goal state
goal_hand = None
goal_on = {
    "red": "table",
    "green": "red",
    "yellow": "green",
    "blue": "yellow",
}

def is_clear(state_on, block):
    """A block is clear if no other block is on it."""
    return all(sup != block for sup in state_on.values())

def serialize(hand, on):
    """Create a hashable representation of a state."""
    items = tuple(sorted(on.items()))
    return (hand, items)

def actions(state_hand, state_on):
    """Generate all applicable actions from a state."""
    # Compute clear blocks
    clear = {b for b in BLOCKS if is_clear(state_on, b)}
    # If a block is being held, it's not in state_on, but considered clear.
    # However, a held block cannot be clear for stacking onto it.
    # We'll treat only blocks in 'clear' set that are not held.
    for block in BLOCKS:
        # PICKUP: hand empty, block on table, block clear
        if state_hand is None and block in clear and state_on.get(block) == "table":
            yield ("pickup", block)
        # PUTDOWN: hand holds block
        if state_hand == block:
            yield ("putdown", block)
        # STACK: hand holds block, target clear
        if state_hand == block:
            for target in clear:
                if target != block:
                    yield ("stack", block, target)
        # UNSTACK: hand empty, block clear, block on another block
        if state_hand is None and block in clear:
            support = state_on.get(block)
            if support and support != "table":
                yield ("unstack", block, support)

def apply(state_hand, state_on, action):
    """Return new state after applying action."""
    new_hand = state_hand
    new_on = dict(state_on)  # shallow copy
    act = action[0]
    if act == "pickup":
        _, blk = action
        new_hand = blk
        # remove blk from on mapping (it was on table)
        new_on.pop(blk, None)
    elif act == "putdown":
        _, blk = action
        new_hand = None
        new_on[blk] = "table"
    elif act == "stack":
        _, blk, target = action
        new_hand = None
        new_on[blk] = target
    elif act == "unstack":
        _, blk, support = action
        new_hand = blk
        # remove relation blk -> support
        new_on.pop(blk, None)
    else:
        raise ValueError("unknown action")
    return new_hand, new_on

def is_goal(state_hand, state_on):
    return state_hand == goal_hand and state_on == goal_on

def bfs():
    start = (initial_hand, initial_on)
    start_key = serialize(*start)
    queue = deque()
    queue.append( (start, []) )
    visited = {start_key}
    while queue:
        (hand, on), plan = queue.popleft()
        if is_goal(hand, on):
            return plan
        for act in actions(hand, on):
            new_hand, new_on = apply(hand, on, act)
            key = serialize(new_hand, new_on)
            if key in visited:
                continue
            visited.add(key)
            queue.append( ((new_hand, new_on), plan + [act]) )
    return None

def format_action(act):
    if act[0] in ("pickup", "putdown"):
        return f"({act[0]} {act[1]})"
    else:
        return f"({act[0]} {act[1]} {act[2]})"

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for act in plan:
            print(format_action(act))

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import collections
import sys

# ------------------------------------------------------------
# Problem definition
# ------------------------------------------------------------
N = 13  # blocks are 1..13
TABLE = 0

# initial configuration
init_on = [0] * (N + 1)  # index 0 unused
# on table
for b in [10, 12, 7, 13, 3, 4, 9, 6]:
    init_on[b] = TABLE
# stacked
init_on[11] = 7
init_on[2] = 11
init_on[5] = 13
init_on[8] = 4
init_on[1] = 6

# goal configuration
goal_on = [0] * (N + 1)
goal_on[6] = TABLE
goal_on[13] = 6

goal_on[2] = TABLE
goal_on[8] = 2
goal_on[7] = 8
goal_on[1] = 7

goal_on[5] = TABLE
goal_on[9] = 5

goal_on[12] = TABLE
goal_on[3] = 12
goal_on[11] = 3
goal_on[4] = 11

goal_on[10] = TABLE

# ------------------------------------------------------------
# Helper functions
# ------------------------------------------------------------
def clear_blocks(on):
    """Return a set of blocks that have nothing on top of them."""
    occupied = set(on[b] for b in range(1, N + 1) if on[b] != TABLE)
    return {b for b in range(1, N + 1) if b not in occupied}

def count_stacks(on):
    """Number of blocks directly on the table."""
    return sum(1 for b in range(1, N + 1) if on[b] == TABLE)

def state_key(holding, on):
    """Hashable representation for visited set."""
    return (holding, tuple(on[1:]))

def is_goal(holding, on):
    return holding == 0 and on[1:] == goal_on[1:]

def format_action(act):
    """Convert internal action tuple to required string."""
    if act[0] == 'pickup':
        return f"(pickup block{act[1]})"
    if act[0] == 'putdown':
        return f"(putdown block{act[1]})"
    if act[0] == 'unstack':
        return f"(unstack block{act[1]} block{act[2]})"
    if act[0] == 'stack':
        return f"(stack block{act[1]} block{act[2]})"
    raise ValueError

# ------------------------------------------------------------
# BFS search
# ------------------------------------------------------------
def bfs():
    start_on = init_on[:]
    start_holding = 0
    start_state = (start_holding, start_on)
    queue = collections.deque()
    queue.append((start_state, []))
    visited = {state_key(start_holding, start_on)}
    first_move_done = False

    while queue:
        (holding, on), plan = queue.popleft()

        # Goal test
        if is_goal(holding, on):
            return plan

        # Determine clear blocks
        clear = clear_blocks(on)

        # ----------------------------------------------------
        # Generate actions
        # ----------------------------------------------------
        # 1. pickup from table
        if holding == 0:
            for b in clear:
                if on[b] == TABLE:
                    new_on = on[:]
                    new_on[b] = TABLE  # stays table but will be considered held
                    new_holding = b
                    new_plan = plan + [('pickup', b)]
                    # after action we have one less stack
                    if not first_move_done:
                        # first move, we allow stack count change but must become 5 afterwards
                        if count_stacks(new_on) != 5:
                            continue
                    else:
                        if count_stacks(new_on) != 5:
                            continue
                    key = state_key(new_holding, new_on)
                    if key not in visited:
                        visited.add(key)
                        queue.append(((new_holding, new_on), new_plan))
        # 2. putdown onto table
        if holding != 0:
            b = holding
            new_on = on[:]
            new_on[b] = TABLE
            new_holding = 0
            new_plan = plan + [('putdown', b)]
            if first_move_done:
                if count_stacks(new_on) != 5:
                    pass  # illegal, skip
                else:
                    key = state_key(new_holding, new_on)
                    if key not in visited:
                        visited.add(key)
                        queue.append(((new_holding, new_on), new_plan))
            else:
                # this would increase stack count -> cannot satisfy eventual 5
                pass

        # 3. unstack X Y
        if holding == 0:
            for x in clear:
                y = on[x]
                if y != TABLE:
                    new_on = on[:]
                    new_on[x] = TABLE  # temporarily removed
                    new_holding = x
                    new_plan = plan + [('unstack', x, y)]
                    if not first_move_done:
                        if count_stacks(new_on) != 5:
                            continue
                    else:
                        if count_stacks(new_on) != 5:
                            continue
                    key = state_key(new_holding, new_on)
                    if key not in visited:
                        visited.add(key)
                        queue.append(((new_holding, new_on), new_plan))

        # 4. stack X Y
        if holding != 0:
            x = holding
            for y in clear:
                if y == x:
                    continue
                new_on = on[:]
                new_on[x] = y
                new_holding = 0
                new_plan = plan + [('stack', x, y)]
                if first_move_done:
                    if count_stacks(new_on) != 5:
                        continue
                else:
                    # first stack action must bring stacks to 5
                    if count_stacks(new_on) != 5:
                        continue
                key = state_key(new_holding, new_on)
                if key not in visited:
                    visited.add(key)
                    queue.append(((new_holding, new_on), new_plan))

        # Update flag after leaving initial state
        if not first_move_done and (holding != 0 or any(on[b] != init_on[b] for b in range(1, N + 1))):
            first_move_done = True

    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
        return
    for act in plan:
        print(format_action(act))

if __name__ == "__main__":
    main()

