from collections import deque

# Blocks
blocks = ["block1", "block2", "block3", "block4"]

# Initial state: all on table, arm empty
init_on = {b: "table" for b in blocks}
init_holding = None

# Goal state: a single stack 4(bottom) -> 2 -> 1 -> 3 (top)
goal_on = {
    "block4": "table",
    "block2": "block4",
    "block1": "block2",
    "block3": "block1",
}
goal_holding = None

def state_key(on, holding):
    """Immutable representation for visited set."""
    items = tuple(sorted(on.items()))
    return (items, holding)

def clear_blocks(on):
    """Return set of blocks that have nothing on them."""
    occupied = {v for v in on.values() if v != "table"}
    return {b for b in blocks if b not in occupied}

def successors(on, holding):
    """Generate (new_on, new_holding, action_str) tuples."""
    clear = clear_blocks(on)
    # arm empty: can pickup or unstack
    if holding is None:
        # pickup from table
        for b in blocks:
            if on[b] == "table" and b in clear:
                new_on = on.copy()
                new_holding = b
                act = f"(pickup {b})"
                yield new_on, new_holding, act
        # unstack
        for b in blocks:
            y = on[b]
            if y != "table" and b in clear:
                new_on = on.copy()
                new_on[b] = "table"
                new_holding = b
                act = f"(unstack {b} {y})"
                yield new_on, new_holding, act
    else:
        # holding a block: can putdown or stack
        # putdown on table
        new_on = on.copy()
        new_on[holding] = "table"
        act = f"(putdown {holding})"
        yield new_on, None, act
        # stack onto a clear block (cannot stack onto itself)
        for y in clear:
            if y == holding:
                continue
            new_on = on.copy()
            new_on[holding] = y
            act = f"(stack {holding} {y})"
            yield new_on, None, act

def is_goal(on, holding):
    return holding == goal_holding and all(on[b] == goal_on[b] for b in blocks)

def bfs():
    start_key = state_key(init_on, init_holding)
    queue = deque()
    queue.append((init_on, init_holding, []))
    visited = {start_key}
    while queue:
        on, holding, plan = queue.popleft()
        if is_goal(on, holding):
            return plan
        for new_on, new_holding, act in successors(on, holding):
            key = state_key(new_on, new_holding)
            if key in visited:
                continue
            visited.add(key)
            queue.append((new_on, new_holding, plan + [act]))
    return None

def main():
    plan = bfs()
    if plan is None:
        print("No plan")
    else:
        for line in plan:
            print(line)

if __name__ == "__main__":
    main()

