            if on[b] == 0:
                new_on = on.copy()
                new_on[b] = None  # being held
                result.append((f"(pickup block{b})", (b, new_on)))
        # unstack
        for b in clear:
            if on[b] != 0 and on[b] is not None:
                a = on[b]
                new_on = on.copy()
                new_on[b] = None
                result.append((f"(unstack block{b} block{a})", (b, new_on)))
    else:
        # putdown
        new_on = on.copy()
        new_on[holding] = 0
        result.append((f"(putdown block{holding})", (None, new_on)))
        # stack onto any clear block (except itself)
        for b in clear:
            if b == holding:
                continue
            new_on = on.copy()
            new_on[holding] = b
            result.append((f"(stack block{holding} block{b})", (None, new_on)))
