import collections

# Blocks
blocks = ['block1', 'block2', 'block3', 'block4', 'block5', 'block6', 'block7']

# Initial state: mapping block -> what it is on ('table' or another block)
init_on = {
    'block5': 'table',
    'block3': 'block5',
    'block7': 'table',
    'block1': 'table',
    'block2': 'table',
    'block4': 'block2',
    'block6': 'table',
}

# Goal: every block on table
def is_goal(state_on):
    return all(state_on[b] == 'table' for b in blocks)

# Helper to compute which blocks are clear (nothing on top)
def compute_clear(state_on):
    occupied = {state_on[b] for b in blocks if state_on[b] != 'table'}
    return {b for b in blocks if b not in occupied}

# Generate possible actions from a state
def successors(state_on, holding):
    clear = compute_clear(state_on)
    succ = []

    # pickup X : arm empty, X clear, X on table
    if holding is None:
        for b in blocks:
            if state_on[b] == 'table' and b in clear:
                new_on = dict(state_on)
                succ.append(((b, new_on), f'(pickup {b})'))

    # putdown X : holding X
    if holding is not None:
        b = holding
        new_on = dict(state_on)
        new_on[b] = 'table'
        succ.append(((None, new_on), f'(putdown {b})'))

    # unstack X Y : arm empty, X clear, X on Y
    if holding is None:
        for b in blocks:
            if b in clear:
                y = state_on[b]
                if y != 'table':
                    new_on = dict(state_on)
                    new_on[b] = 'table'  # will be held, so temporarily on table
                    succ.append(((b, new_on), f'(unstack {b} {y})'))

    # stack X Y : holding X, Y clear, Y is not block2 (fragile constraint)
    if holding is not None:
        x = holding
        for y in blocks:
            if y in clear and y != 'block2' and y != x:
                new_on = dict(state_on)
                new_on[x] = y
                succ.append(((None, new_on), f'(stack {x} {y})'))

    return succ

# BFS search
def bfs():
    start = (None, init_on)  # (holding, on mapping)
    queue = collections.deque()
    queue.append((start, []))
    visited = set()

    def state_key(state):
        holding, on = state
        # tuple sorted by block name for deterministic hash
        on_items = tuple(sorted(on.items()))
        return (holding, on_items)

    visited.add(state_key(start))

    while queue:
        (holding, on), plan = queue.popleft()
        if is_goal(on) and holding is None:
            return plan
        for (new_holding, new_on), act in successors(on, holding):
            new_state = (new_holding, new_on)
            key = state_key(new_state)
            if key not in visited:
                visited.add(key)
                queue.append((new_state, plan + [act]))
    return None

plan = bfs()
if plan is None:
