import heapq

# Blocks
blocks = [f'block{i}' for i in range(1, 16)]

# Initial state: all on table, arm empty
initial_pos = {b: 'table' for b in blocks}
initial_holding = None

# Goal configuration
goal_pos = {
    'block15': 'table',
    'block8': 'block15',
    'block2': 'block8',
    'block6': 'table',
    'block3': 'block6',
    'block9': 'block3',
    'block11': 'table',
    'block7': 'block11',
    'block13': 'block7',
    'block1': 'block13',
    'block5': 'block1',
    'block14': 'block5',
    'block10': 'table',
    'block12': 'block10',
    'block4': 'block12',
}
# any block not listed stays on table (they are already on table in goal)
for b in blocks:
    goal_pos.setdefault(b, 'table')

def clear_blocks(pos):
    """Return set of blocks that have nothing on top."""
    occupied = {v for v in pos.values() if v != 'table'}
    return {b for b in blocks if b not in occupied}

def heuristic(pos):
    """Number of blocks not on correct support."""
    return sum(1 for b in blocks if pos[b] != goal_pos[b])

def state_key(holding, pos, moved1):
    """Hashable representation for visited set."""
    return (holding, tuple(sorted(pos.items())), moved1)

def applicable_actions(state):
    holding, pos, moved1 = state
    clear = clear_blocks(pos)
    actions = []

    # actions when arm empty
    if holding is None:
        # pickup from table
        for b in clear:
            if pos[b] == 'table':
                actions.append(('pickup', b))
        # unstack from another block
        for b in clear:
            under = pos[b]
            if under != 'table':
                actions.append(('unstack', b, under))
    else:
        # putdown to table
        actions.append(('putdown', holding))
        # stack onto a clear block
        for b in clear:
            if b != holding:
                actions.append(('stack', holding, b))

    # Enforce ordering constraint: block2 cannot be moved before block1 has moved
    filtered = []
    for act in actions:
        if act[0] in ('pickup', 'unstack', 'stack', 'putdown'):
            moved_block = act[1]
            if moved_block == 'block2' and not moved1:
                continue  # illegal before block1 moved
        filtered.append(act)
    return filtered

def apply_action(state, action):
    holding, pos, moved1 = state
    new_pos = pos.copy()
    new_holding = holding
    moved1_new = moved1

    if action[0] == 'pickup':
        b = action[1]
        new_holding = b
        new_pos[b] = None  # temporarily not on anything
        if b == 'block1':
            moved1_new = True
    elif action[0] == 'unstack':
        b, under = action[1], action[2]
        new_holding = b
        new_pos[b] = None
        if b == 'block1':
            moved1_new = True
    elif action[0] == 'putdown':
        b = action[1]
        new_holding = None
        new_pos[b] = 'table'
    elif action[0] == 'stack':
        b, under = action[1], action[2]
        new_holding = None
        new_pos[b] = under
        if b == 'block1':
            moved1_new = True
    else:
        raise ValueError('unknown action')
    return (new_holding, new_pos, moved1_new)

def is_goal(state):
    _, pos, _ = state
    return all(pos[b] == goal_pos[b] for b in blocks)

def format_action(action):
    if action[0] in ('pickup', 'putdown'):
        return f'({action[0]} {action[1]})'
    else:
        return f'({action[0]} {action[1]} {action[2]})'

def search():
    start = (initial_holding, initial_pos, False)
    frontier = [(heuristic(initial_pos), 0, start, [])]  # (f, g, state, plan)
    visited = set()

    while frontier:
        f, g, state, plan = heapq.heappop(frontier)
        key = state_key(*state)
        if key in visited:
            continue
        visited.add(key)

        if is_goal(state):
            return plan

        for act in applicable_actions(state):
            nxt = apply_action(state, act)
            nxt_key = state_key(*nxt)
            if nxt_key in visited:
                continue
            new_plan = plan + [act]
            h = heuristic(nxt[1])
            heapq.heappush(frontier, (g + 1 + h, g + 1, nxt, new_plan))
    return None

def main():
    plan = search()
    if plan is None:
        print('No plan')
    else:
        for act in plan:
            print(format_action(act))

if __name__ == '__main__':
    main()

import collections

# Block indices: block1 -> 0, block2 -> 1, ..., block12 -> 11
N = 12

# Initial support list: support[i] = 0 for table, else block number (1-12)
# From description:
# Stack1: 9 on table, 2 on 9, 1 on 2, 6 on 1
# Stack2: 7 on table, 5 on 7
# Stack3: 10 on table, 4 on 10, 3 on 4, 12 on 3, 8 on 12, 11 on 8
init_support = [0] * N
init_support[8] = 0   # block9 on table
init_support[1] = 9   # block2 on 9
init_support[0] = 2   # block1 on 2
init_support[5] = 1   # block6 on 1

init_support[6] = 0   # block7 on table
init_support[4] = 7   # block5 on 7

init_support[9] = 0   # block10 on table
init_support[3] = 10  # block4 on 10
init_support[2] = 4   # block3 on 4
init_support[11] = 3  # block12 on 3
init_support[7] = 12  # block8 on 12
init_support[10] = 8  # block11 on 8

# Goal conditions
table_set = {9,12,10,5,6,7,2,3,4,8}  # block numbers that must be on table
goal_support = [None] * N
for b in range(1, N+1):
    if b in table_set:
        goal_support[b-1] = 0
goal_support[10] = 5   # block11 on block5
goal_support[0] = 4    # block1 on block4

def is_clear(support, idx):
    """Return True if block idx (0‑based) has nothing on top."""
    for s in support:
        if s == idx+1:
            return False
    return True

def state_key(holding, support):
    return (holding, tuple(support))

def goal_test(holding, support):
    if holding is not None:
        return False
    for i, sup in enumerate(support):
        g = goal_support[i]
        if g is None:
            continue
        if sup != g:
            return False
    return True

def successors(holding, support):
    clear = [is_clear(support, i) for i in range(N)]
    # generate actions
    # pickup X
    if holding is None:
        for i in range(N):
            if support[i] == 0 and clear[i]:
                new_support = list(support)
                # block removed from table, remains clear (nothing on it)
                # no change to support list needed (still 0)
                yield ('pickup', i), (i, new_support)
    # putdown X
    if holding is not None:
        i = holding
        new_support = list(support)
        new_support[i] = 0
        yield ('putdown', i), (None, new_support)
    # stack X Y
    if holding is not None:
        i = holding
        for j in range(N):
            if clear[j] and i != j:
                new_support = list(support)
                new_support[i] = j+1
                yield ('stack', i, j), (None, new_support)
    # unstack X Y
    if holding is None:
        for i in range(N):
            if clear[i]:
                sup = support[i]
                if sup != 0:
                    j = sup - 1
                    new_support = list(support)
                    new_support[i] = 0
                    yield ('unstack', i, j), (i, new_support)

def bfs():
    start = (None, init_support)
    queue = collections.deque()
    queue.append((start, []))
    visited = set()
    visited.add(state_key(*start))
    while queue:
        (holding, support), path = queue.popleft()
        if goal_test(holding, support):
            return path
        for action, (new_holding, new_support) in successors(holding, support):
            key = state_key(new_holding, new_support)
            if key in visited:
                continue
            visited.add(key)
            queue.append(((new_holding, new_support), path + [action]))
    return None

plan = bfs()
if plan is None:
    print("No plan")
else:
    for act in plan:
        if act[0] == 'pickup':
            print(f"(pickup block{act[1]+1})")
        elif act[0] == 'putdown':
            print(f"(putdown block{act[1]+1})")
        elif act[0] == 'stack':
            print(f"(stack block{act[1]+1} block{act[2]+1})")
        elif act[0] == 'unstack':
            print(f"(unstack block{act[1]+1} block{act[2]+1})")
